1	import React, { useState, useRef, useEffect } from 'react';
2	import { motion, Variants } from 'framer-motion';
3	import clsx from 'clsx';
4	import {
5	  FileSliders,
6	  Box,
7	  MousePointer2,
8	  Move3d,
9	  RotateCw,
10	  Maximize,
11	  Upload,
12	  Code,
13	  Maximize2,
14	  Eye,
15	  Palette,
16	  Layers
17	} from 'lucide-react';
18	import styles from './Sidebar.module.scss';
19	import { CustomTooltip } from './CustomTooltip';
20	
21	// Doit correspondre à ViewCube.module.scss (`.container`) : la colonne d'outils du mode
22	// Prévisualisation vient se coller au même bord droit, juste sous le gizmo.
23	const VIEWCUBE_RIGHT = 24;
24	const VIEWCUBE_BOTTOM = 70 + 130; // top + height
25	const PREVIEW_TOOLBAR_TOP_GAP = 10; // marge entre le bas du ViewCube et le haut de la colonne
26	const PREVIEW_TOOLBAR_WIDTH = 56; // largeur de la colonne de calques en mode Prévisualisation
27	
28	// Position de repos (mode box, sans transformation) du haut de `.bottomToolbar` : top du
29	// `.container` (20px) + hauteur du `.topToolbar` (42px de bouton + 8px de padding de
30	// chaque côté = 58px) + le gap de la pile flex (10px). Doit rester en phase avec
31	// Sidebar.module.scss si ces valeurs changent.
32	const BOTTOM_TOOLBAR_REST_TOP = 20 + 58 + 10;
33	
34	// Durée totale de l'animation de déplacement/déformation du conteneur `.bottomToolbar`
35	// (voir son `transition` plus bas) : c'est le délai avant lequel les icônes du mode cible
36	// ne doivent JAMAIS commencer à apparaître (cf. `iconVariants.visible`), dans tous les sens
37	// de transition. Partagée par les deux pour qu'elles ne puissent pas diverger.
38	const CONTAINER_RESHAPE_DURATION = 1.1;
39	
40	interface SidebarProps {
41	  activeTab: '3d-view' | 'settings' | 'developer';
42	  onTabChange: (tab: 'box' | 'settings' | 'developer') => void;
43	  onOpenModel?: () => void;
44	}
45	
46	export const Sidebar: React.FC<SidebarProps> = ({
47	  activeTab,
48	  onTabChange,
49	  onOpenModel
50	}) => {
51	  const [activeTool, setActiveTool] = useState<'select' | 'move' | 'rotate' | 'scale' | 'texture' | 'layers'>('select');
52	  const [isPreviewActive, setIsPreviewActive] = useState(false);
53	  // Géométrie du conteneur juste avant de lancer la transition en cours : mesurée à la volée
54	  // (voir `playSpaceTransition`) quel que soit le mode de départ (slicer, prévisualisation
55	  // ou modélisation), pour que l'animation de conteneur parte toujours de sa forme réelle et
56	  // non d'une valeur figée valable pour un seul sens de transition.
57	  const [fromGeometry, setFromGeometry] = useState<{ x: number; y: number; width: number; height: number; borderRadius: number } | null>(null);
58	  // Largeur naturelle de la barre slicer (mode "box") : son contenu (8 boutons + 2
59	  // séparateurs) ne change jamais, donc une mesure une fois montée suffit — c'est la valeur
60	  // cible numérique vers laquelle animer au retour au mode slicer (une keyframe `"auto"`
61	  // mélangée à des nombres dans le même tableau n'anime pas correctement avec framer-motion).
62	  const [boxWidth, setBoxWidth] = useState<number | null>(null);
63	  // Décalage horizontal (en x) à appliquer en mode Prévisualisation pour que la colonne
64	  // d'outils vienne se coller au bord droit de l'écran, juste sous le gizmo ViewCube
65	  // (position fixe à `right: 24px`, voir ViewCube.module.scss) — recalculé au resize car
66	  // `.bottomToolbar` est centré par le flex column de `.container` (`left: 50%`), donc son
67	  // décalage nécessaire dépend de la largeur de la fenêtre.
68	  const [previewX, setPreviewX] = useState(0);
69	  // Décalage vertical (en y) additionnel en mode Prévisualisation, calculé pour amener le
70	  // haut de la colonne juste sous le ViewCube, quelle que soit sa position de repos réelle
71	  // (dépend de la hauteur du bandeau d'onglets du haut).
72	  const [previewY, setPreviewY] = useState(0);
73	  const bottomToolbarRef = useRef<HTMLDivElement>(null);
74	  const fileInputRef = useRef<HTMLInputElement>(null);
75	
76	  const topToolbarRef = useRef<HTMLDivElement>(null);
77	  // Slot où ModelingSidebar injecte ses boutons CAD via un portail (id stable plutôt qu'un
78	  // ref transmis en prop : les deux composants sont des siblings montés indépendamment dans
79	  // Index.tsx, un id DOM est la façon la plus simple de se retrouver).
80	  const modelingSlotRef = useRef<HTMLDivElement>(null);
81	  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());
82	  const [indicatorStyle, setIndicatorStyle] = React.useState<React.CSSProperties>({});
83	
84	  /** L'onglet « Modélisation » porte la valeur 'settings'. */
85	  const isModeling = activeTab === 'settings';
86	
87	  // Gabarit cible du conteneur commun pour chaque mode — voir le commentaire au-dessus de
88	  // `.bottomToolbar` dans le JSX pour la logique d'animation qui s'en sert. En mode
89	  // Prévisualisation, x/y viennent coller la colonne au bord droit de l'écran juste sous le
90	  // ViewCube (voir l'effet qui calcule `previewX`/`previewY` plus haut) plutôt qu'un
91	  // décalage fixe indépendant de la largeur de la fenêtre.
92	  const targetGeometry = isModeling
93	    ? { x: 0, y: 0, width: 260, height: 50, borderRadius: 14 } // barre CAD (6 boutons de 38px)
94	    : isPreviewActive
95	      ? { x: previewX, y: previewY, width: PREVIEW_TOOLBAR_WIDTH, height: 340, borderRadius: 20 } // colonne de calques
96	      : { x: 0, y: 0, width: boxWidth ?? 332, height: 44, borderRadius: 22 }; // barre slicer
97	
98	  const handleUploadClick = () => {
99	    fileInputRef.current?.click();
100	  };
101	
102	  const SPACE_LABELS: Record<'box' | 'settings' | 'developer' | 'layers', string> = {
103	    box: 'Préparation',
104	    settings: 'Modélisation',
105	    developer: 'Dev',
106	    layers: 'Prévisualisation',
107	  };
108	
109	  /**
110	   * Joue le rideau "APEX / <espace>" (voir SpaceTransitionOverlay) puis exécute `onCovered`
111	   * une fois l'écran masqué — c'est là, et pas avant, que le vrai changement d'onglet doit
112	   * avoir lieu pour ne jamais être visible pendant la transition. Mesure aussi la forme
113	   * actuelle du conteneur d'outils juste avant : quel que soit le mode de départ (slicer,
114	   * prévisualisation ou modélisation), c'est de là que doit partir l'animation de
115	   * déformation vers le mode suivant — jamais une valeur figée valable pour un seul sens.
116	   */
117	  const playSpaceTransition = (label: string, onCovered: () => void) => {
118	    if (bottomToolbarRef.current) {
119	      const rect = bottomToolbarRef.current.getBoundingClientRect();
120	      const computedRadius = parseFloat(getComputedStyle(bottomToolbarRef.current).borderTopLeftRadius) || 22;
121	      // `x`/`y` ne sont pas lisibles depuis le DOM (ce sont des translate posés par
122	      // framer-motion, pas une position absolue) : on reprend ceux du mode qu'on est en
123	      // train de quitter, calculés par la même table que `targetGeometry` ci-dessous.
124	      setFromGeometry({
125	        x: targetGeometry.x,
126	        y: targetGeometry.y,
127	        width: rect.width,
128	        height: rect.height,
129	        borderRadius: computedRadius,
130	      });
131	    }
132	    window.dispatchEvent(new CustomEvent('apex-space-transition', { detail: { label, onCovered } }));
133	  };
134	
135	  const handleTopTabClick = (tabName: 'box' | 'settings' | 'developer') => {
136	    playSpaceTransition(SPACE_LABELS[tabName], () => {
137	      setActiveTool('select');
138	      onTabChange(tabName);
139	      setIsPreviewActive(false);
140	      window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
141	    });
142	  };
143	
144	  const handleToolClick = (tool: 'select' | 'move' | 'rotate' | 'scale' | 'texture') => {
145	    const newTool = activeTool === tool ? 'select' : tool;
146	    setActiveTool(newTool);
147	    window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
148	  };
149	
150	  const handleLayerClick = () => {
151	    const entering = activeTool !== 'layers';
152	
153	    if (entering) {
154	      // L'ancien fondu séquencé des panneaux (avant le rideau plein écran) n'a plus de raison
155	      // d'être : le rideau masque déjà tout pendant que ce switch se produit, donc tout bascule
156	      // d'un coup sous le voile plutôt qu'en deux temps visibles.
157	      playSpaceTransition(SPACE_LABELS.layers, () => {
158	        setActiveTool('layers');
159	        setIsPreviewActive(true);
160	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'layers' } }));
161	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: true } }));
162	      });
163	    } else {
164	      playSpaceTransition(SPACE_LABELS.box, () => {
165	        setActiveTool('select');
166	        setIsPreviewActive(false);
167	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
168	        window.dispatchEvent(new CustomEvent('apex-preview-toggled', { detail: { active: false } }));
169	      });
170	    }
171	  };
172	
173	  useEffect(() => {
174	    const handleKeyDown = (e: KeyboardEvent) => {
175	      if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement)?.tagName)) {
176	        return;
177	      }
178	
179	      const key = e.key.toLowerCase();
180	      if (key === 'm') {
181	        const newTool = activeTool === 'move' ? 'select' : 'move';
182	        setActiveTool(newTool);
183	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
184	      } else if (key === 'r') {
185	        const newTool = activeTool === 'rotate' ? 'select' : 'rotate';
186	        setActiveTool(newTool);
187	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
188	      } else if (key === 's') {
189	        const newTool = activeTool === 'scale' ? 'select' : 'scale';
190	        setActiveTool(newTool);
191	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
192	      } else if (key === 't') {
193	        const newTool = activeTool === 'texture' ? 'select' : 'texture';
194	        setActiveTool(newTool);
195	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: newTool } }));
196	      } else if (key === 'escape') {
197	        setActiveTool('select');
198	        window.dispatchEvent(new CustomEvent('apex-tool-changed', { detail: { tool: 'select' } }));
199	      }
200	    };
201	
202	    window.addEventListener('keydown', handleKeyDown);
203	    return () => {
204	      window.removeEventListener('keydown', handleKeyDown);
205	    };
206	  }, [activeTool]);
207	
208	  // Mesure la largeur naturelle de la barre slicer dès qu'on la voit au repos (mode box,
209	  // aucune transition en cours) — la toute première fois, et à nouveau si jamais elle
210	  // n'a pas encore été capturée (ex : l'app démarre directement sur un autre onglet).
211	  useEffect(() => {
212	    if (boxWidth === null && !isModeling && !isPreviewActive && bottomToolbarRef.current) {
213	      setBoxWidth(bottomToolbarRef.current.getBoundingClientRect().width);
214	    }
215	  }, [boxWidth, isModeling, isPreviewActive]);
216	
217	  // Décalage x/y nécessaire pour que la colonne d'outils du mode Prévisualisation vienne se
218	  // coller au bord droit de l'écran, juste sous le ViewCube. `.container` (l'ancêtre direct)
219	  // est centré par `left: 50%` quel que soit l'état, donc son centre horizontal vaut
220	  // toujours exactement `window.innerWidth / 2` — inutile de mesurer le DOM, une formule
221	  // suffit et reste valable pendant toute animation. Le `top` de repos du conteneur est lui
222	  // fixe (posé par le CSS de `.container`/`.topToolbar`, pas par une mesure runtime).
223	  useEffect(() => {
224	    const recompute = () => {
225	      const restCenterX = window.innerWidth / 2;
226	      const targetCenterX = window.innerWidth - VIEWCUBE_RIGHT - PREVIEW_TOOLBAR_WIDTH / 2;
227	      const targetTop = VIEWCUBE_BOTTOM + PREVIEW_TOOLBAR_TOP_GAP;
228	
229	      setPreviewX(targetCenterX - restCenterX);
230	      setPreviewY(targetTop - BOTTOM_TOOLBAR_REST_TOP);
231	    };
232	
233	    recompute();
234	    window.addEventListener('resize', recompute);
235	    return () => window.removeEventListener('resize', recompute);
236	  }, []);
237	
238	  useEffect(() => {
239	    if (topToolbarRef.current && buttonRefs.current.size > 0) {
240	      const activeButtonKey = activeTool === 'layers' ? 'layers' : (activeTab === '3d-view' ? 'box' : activeTab);
241	      const activeButton = buttonRefs.current.get(activeButtonKey);
242	
243	      if (activeButton) {
244	        const toolbarRect = topToolbarRef.current.getBoundingClientRect();
245	        const buttonRect = activeButton.getBoundingClientRect();
246	
247	        setIndicatorStyle({
248	          width: buttonRect.width,
249	          height: buttonRect.height,
250	          left: buttonRect.left - toolbarRect.left,
251	          top: buttonRect.top - toolbarRect.top,
252	          opacity: 1,
253	        });
254	      } else {
255	        setIndicatorStyle((prev) => ({ ...prev, opacity: 0 }));
256	      }
257	    }
258	  }, [activeTab, activeTool]);
259	
260	  const iconVariants: Variants = {
261	    // Les icônes du mode cible n'apparaissent qu'UNE FOIS le reshape du conteneur terminé
262	    // (durée totale de l'animation de `.bottomToolbar`, voir CONTAINER_RESHAPE_DURATION) —
263	    // dans tous les sens de transition, pas seulement Prévisualisation→Modélisation. Sans ce
264	    // délai de base, les icônes du nouveau mode démarraient leur propre petit délai en
265	    // cascade (`i*0.04`) dès le changement de state React, bien avant que le conteneur ait
266	    // fini de se déplacer/déformer.
267	    visible: (i: number) => ({
268	      opacity: 1,
269	      y: 0,
270	      scale: 1,
271	      transition: {
272	        delay: CONTAINER_RESHAPE_DURATION + i * 0.04,
273	        duration: 0.3,
274	        ease: [0.16, 1, 0.3, 1] as const
275	      }
276	    }),
277	    // La sortie, elle, doit rester immédiate : les icônes du mode qu'on quitte doivent avoir
278	    // disparu AVANT que le conteneur ne commence à se déformer (cf. keyframes `times` de
279	    // `.bottomToolbar` : vidage sur les premiers 45%, déformation sur les 55% restants).
280	    hidden: (i: number) => ({
281	      opacity: 0,
282	      y: 15,
283	      scale: 0.95,
284	      transition: {
285	        delay: i * 0.04,
286	        duration: 0.25,
287	        ease: [0.25, 1, 0.5, 1] as const
288	      }
289	    })
290	  };
291	
292	  return (
293	    <div className={styles.container} data-apex-chrome-panel>
294	      {/* Top Toolbar (Navigation & Main Views) */}
295	      <div
296	        ref={topToolbarRef}
297	        className={clsx(styles.toolbar, styles.topToolbar)}
298	      >
299	        <div className={styles.activeIndicator} style={indicatorStyle}></div>
300	
301	        <CustomTooltip content="Apex Slicer Studio" description="Logiciel de préparation et de découpe 3D haute performance pour l'impression additive professionnelle.">
302	          <div className={styles.logoContainer}>
303	            <img src="/logo.svg" alt="Logo" className={styles.logoImg} />
304	          </div>
305	        </CustomTooltip>
306	
307	        <div className={styles.topSeparator} />
308	
309	        <CustomTooltip content="Vue 3D Perspective" description="Basculez sur l'espace de travail principal pour inspecter et manipuler vos modèles sur le plateau d'impression.">
310	          <button
311	            ref={(el) => { if (el) buttonRefs.current.set('box', el); }}
312	            className={clsx(styles.button, styles.topButton, {
313	              [styles.active]: activeTab === '3d-view' && !isPreviewActive,
314	            })}
315	            onClick={() => handleTopTabClick('box')}
316	          >
317	            <FileSliders size={22} />
318	            <span className={styles.topButtonLabel}>Préparation</span>
319	          </button>
320	        </CustomTooltip>
321	
322	        <CustomTooltip content="Prévisualisation" description="Visualisez le parcours de la buse et ajustez différents paramètres si cela ne vous convient pas.">
323	          <button
324	            ref={(el) => { if (el) buttonRefs.current.set('layers', el); }}
325	            className={clsx(styles.button, styles.topButton, {
326	              [styles.active]: isPreviewActive,
327	            })}
328	            onClick={handleLayerClick}
329	          >
330	            <Layers size={22} />
331	            <span className={styles.topButtonLabel}>Prévisualisation</span>
332	          </button>
333	        </CustomTooltip>
334	
335	        <CustomTooltip content="Modélisation" description="Accédez aux outils de modélisation et de préparation de votre modèle.">
336	          <button
337	            ref={(el) => { if (el) buttonRefs.current.set('settings', el); }}
338	            className={clsx(styles.button, styles.topButton, {
339	              [styles.active]: activeTab === 'settings',
340	            })}
341	            onClick={() => handleTopTabClick('settings')}
342	          >
343	            <Box size={22} />
344	            <span className={styles.topButtonLabel}>Modélisation</span>
345	          </button>
346	        </CustomTooltip>
347	
348	        <CustomTooltip content="Console Développeur" description="Inspectez les flux G-code générés en temps réel et les journaux de diagnostic système.">
349	          <button
350	            ref={(el) => { if (el) buttonRefs.current.set('developer', el); }}
351	            className={clsx(styles.button, styles.topButton, {
352	              [styles.active]: activeTab === 'developer',
353	            })}
354	            onClick={() => handleTopTabClick('developer')}
355	          >
356	            <Code size={22} />
357	            <span className={styles.topButtonLabel}>Dev</span>
358	          </button>
359	        </CustomTooltip>
360	      </div>
361	
362	      {/* Bottom Toolbar (Action, Manipulation 3D) — UN SEUL conteneur physique pour les 3
363	          modes (slicer / prévisualisation / modélisation) : il ne se démonte jamais, il se
364	          vide de ses icônes, se déplace et se déforme, puis affiche les icônes du mode
365	          suivant. En mode modélisation les boutons CAD ne sont pas rendus ici : ils vivent
366	          dans ModelingSidebar (toute la logique de features y reste), qui les injecte dans
367	          `modelingSlotRef` via un portail — même noeud DOM, contenu apporté par le
368	          propriétaire de sa logique. */}
369	      <motion.div
370	        ref={bottomToolbarRef}
371	        className={clsx(styles.toolbar, styles.bottomToolbar)}
372	        initial={false}
373	        animate={fromGeometry ? {
374	          // Toute transition (slicer ↔ prévisualisation, slicer ↔ modélisation) part
375	          // TOUJOURS de la forme réellement mesurée juste avant (`fromGeometry`) pour
376	          // rejoindre le gabarit du mode cible — un seul et même conteneur qui se vide de
377	          // ses icônes (cf. iconVariants), se déplace et se déforme, jamais deux
378	          // composants qui se croisent.
379	          x: [fromGeometry.x, fromGeometry.x, targetGeometry.x],
380	          y: [fromGeometry.y, fromGeometry.y, targetGeometry.y],
381	          width: [fromGeometry.width, fromGeometry.width, targetGeometry.width],
382	          height: [fromGeometry.height, fromGeometry.height, targetGeometry.height],
383	          borderRadius: [fromGeometry.borderRadius, fromGeometry.borderRadius, targetGeometry.borderRadius],
384	          opacity: 1,
385	          marginTop: 0
386	        } : {
387	          // État initial (avant toute transition jouée) : forme de repos du mode courant,
388	          // sans animation. "auto" tant que la largeur naturelle n'a pas encore été mesurée
389	          // (premier rendu), un nombre dès qu'elle l'est — évite un saut visuel une fois
390	          // `boxWidth` connu puisque `targetGeometry.width` vaudra alors la même valeur.
391	          x: targetGeometry.x,
392	          y: targetGeometry.y,
393	          width: isModeling || boxWidth !== null ? targetGeometry.width : "auto",
394	          height: targetGeometry.height,
395	          borderRadius: targetGeometry.borderRadius,
396	          opacity: 1,
397	          marginTop: 0
398	        }}
399	        transition={{
400	          duration: CONTAINER_RESHAPE_DURATION,
401	          times: [0, 0.45, 1],
402	          ease: [0.25, 1, 0.5, 1]
403	        }}
404	        style={{ originX: 0.5, originY: 0.5, pointerEvents: 'auto' }}
405	      >
406	        <motion.div custom={0} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
407	          <CustomTooltip content="Outil de Sélection" description="Cliquez sur n'importe quel modèle 3D sur le plateau pour le sélectionner et afficher ses propriétés.">
408	            <button
409	              className={clsx(styles.button, styles.bottomButton, {
410	                [styles.active]: activeTool === 'select',
411	              })}
412	              onClick={() => handleToolClick('select')}
413	            >
414	              <MousePointer2 size={16} />
415	            </button>
416	          </CustomTooltip>
417	        </motion.div>
418	
419	        <motion.div custom={1} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
420	          <CustomTooltip content="Outil de Déplacement (Move - M)" description="Affichez les gizmos directionnels pour repositionner précisément l'objet sur le plateau d'impression. (Raccourci : M)">
421	            <button
422	              className={clsx(styles.button, styles.bottomButton, {
423	                [styles.active]: activeTool === 'move',
424	              })}
425	              onClick={() => handleToolClick('move')}
426	            >
427	              <Move3d size={16} />
428	            </button>
429	          </CustomTooltip>
430	        </motion.div>
431	
432	        <motion.div custom={2} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
433	          <CustomTooltip content="Outil de Rotation (Rotate - R)" description="Faites pivoter le modèle selon les axes X, Y et Z pour optimiser son orientation de contact. (Raccourci : R)">
434	            <button
435	              className={clsx(styles.button, styles.bottomButton, {
436	                [styles.active]: activeTool === 'rotate',
437	              })}
438	              onClick={() => handleToolClick('rotate')}
439	            >
440	              <RotateCw size={16} />
441	            </button>
442	          </CustomTooltip>
443	        </motion.div>
444	
445	        <motion.div custom={3} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
446	          <CustomTooltip content="Outil de Mise à l'échelle (Scale - S)" description="Modifiez la taille et les proportions du modèle 3D sur le plateau d'impression. (Raccourci : S)">
447	            <button
448	              className={clsx(styles.button, styles.bottomButton, {
449	                [styles.active]: activeTool === 'scale',
450	              })}
451	              onClick={() => handleToolClick('scale')}
452	            >
453	              <Maximize size={16} />
454	            </button>
455	          </CustomTooltip>
456	        </motion.div>
457	
458	        <motion.div custom={4} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
459	          <CustomTooltip content="Outil Texture & Matériau (Texture - T)" description="Sélectionnez et éditez les textures et propriétés de matériaux du modèle actif. (Raccourci : T)">
460	            <button
461	              className={clsx(styles.button, styles.bottomButton, {
462	                [styles.active]: activeTool === 'texture',
463	              })}
464	              onClick={() => handleToolClick('texture')}
465	            >
466	              <Palette size={16} />
467	            </button>
468	          </CustomTooltip>
469	        </motion.div>
470	
471	        <motion.div custom={5} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
472	          <div className={styles.separator} />
473	        </motion.div>
474	
475	        <motion.div custom={6} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
476	          <CustomTooltip content="Réinitialiser la Caméra" description="Remettez la caméra dans sa position isométrique par défaut face au plateau.">
477	            <button
478	              className={clsx(styles.button, styles.bottomButton)}
479	              onClick={() => window.dispatchEvent(new CustomEvent('apex-reset-camera'))}
480	            >
481	              <Eye size={16} />
482	            </button>
483	          </CustomTooltip>
484	        </motion.div>
485	
486	        <motion.div custom={7} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
487	          <CustomTooltip content="Ajuster à l'Écran (Fit)" description="Zoomez et recentrez la vue automatiquement sur le modèle sélectionné.">
488	            <button
489	              className={clsx(styles.button, styles.bottomButton)}
490	              onClick={() => window.dispatchEvent(new CustomEvent('apex-fit-screen'))}
491	            >
492	              <Maximize2 size={16} />
493	            </button>
494	          </CustomTooltip>
495	        </motion.div>
496	
497	        <motion.div custom={8} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
498	          <div className={styles.separator} />
499	        </motion.div>
500	
501	        <motion.div custom={9} variants={iconVariants} animate={isPreviewActive || isModeling ? "hidden" : "visible"} initial="visible" className="flex items-center">
502	          <CustomTooltip content="Importer un Modèle 3D (.stl, .glb, .gltf)" description="Ouvrez le sélecteur de fichiers pour charger un nouveau fichier 3D avec textures sur le plateau.">
503	            <button
504	              className={clsx(styles.button, styles.bottomButton, styles.uploadActionButton)}
505	              onClick={handleUploadClick}
506	            >
507	              <Upload size={16} />
508	            </button>
509	          </CustomTooltip>
510	        </motion.div>
511	
512	        {/* Mode modélisation : mêmes noeud et animation de conteneur que le mode slicer —
513	            seul le contenu diffère. Les boutons CAD eux-mêmes (logique de features) sont
514	            possédés par ModelingSidebar, qui les injecte ici via un portail (voir
515	            modelingSlotRef) plutôt que d'être dupliqués ou recréés dans ce composant. */}
516	        <motion.div
517	          custom={0}
518	          variants={iconVariants}
519	          animate={isModeling ? "visible" : "hidden"}
520	          initial="hidden"
521	          ref={modelingSlotRef}
522	          id="apex-modeling-toolbar-slot"
523	          className={styles.modelingSlot}
524	        />
525	
526	        <input
527	          type="file"
528	          ref={fileInputRef}
529	          style={{ display: 'none' }}
530	          accept=".stl,.glb,.gltf"
531	          onChange={(e) => {
532	            if (e.target.files?.[0]) {
533	              window.dispatchEvent(
534	                new CustomEvent('apex-import-model', {
535	                  detail: e.target.files[0],
536	                })
537	              );
538	            }
539	            // Réinitialise la valeur pour pouvoir réimporter exactement le même fichier
540	            // à la suite (sinon le navigateur ne redéclenche pas onChange).
541	            e.target.value = '';
542	          }}
543	        />
544	      </motion.div>
545	    </div>
546	  );
547	};

