1	"use client";
2	
3	import React, { useRef, useState, useLayoutEffect } from 'react';
4	import * as BABYLON from 'babylonjs';
5	import 'babylonjs-loaders';
6	import { renderToStaticMarkup } from 'react-dom/server';
7	import { Upload, BoxSelect, LayoutGrid, Trash2 } from 'lucide-react';
8	import { showSuccess, showWarning } from '@/utils/toast';
9	import styles from './Viewport3D.module.scss';
10	
11	const DEFAULT_BLUR_LEVEL = 40;
12	
13	export const Viewport3D = () => {
14	  const canvasRef = useRef<HTMLCanvasElement>(null);
15	  const [contextMenu, setContextMenu] = useState<{ x: number; y: number } | null>(null);
16	  // Le clic droit qui ouvre le menu déclenche ensuite, sur ce même clic, l'événement DOM natif
17	  // `contextmenu` : au moment où celui-ci se déclenche, le rideau de fermeture (qui couvre tout
18	  // l'écran) est déjà monté sous le curseur et en reçoit la cible — sans ce garde-fou, son
19	  // propre `onContextMenu` referme le menu qui vient tout juste de s'ouvrir. On l'arme juste
20	  // avant d'ouvrir et on l'ignore une seule fois, côté rideau.
21	  const suppressNextBackdropContextMenuRef = useRef(false);
22	  const [blurLevel, setBlurLevel] = useState(DEFAULT_BLUR_LEVEL);
23	  // Info-bulle qui suit le curseur pendant la sélection du plan d'esquisse (façon Fusion 360).
24	  const [sketchPlaneHint, setSketchPlaneHint] = useState<{ x: number; y: number } | null>(null);
25	  const [plateActionHint, setPlateActionHint] = useState<{ title: string; x: number; y: number } | null>(null);
26	  // Rectangle de la fenêtre de sélection (clic gauche + drag), en coordonnées écran relatives
27	  // au conteneur — `null` quand aucun drag de sélection n'est en cours. `mode` dépend du sens du
28	  // drag, comme dans la plupart des logiciels de CAO : vers la droite = « window » (ne retient
29	  // que les objets entièrement englobés, contour plein) ; vers la gauche = « crossing » (retient
30	  // tout objet touché, contour pointillé animé + surlignage blanc).
