1	// Fenêtre de sélection (clic gauche + drag) : le mode « crossing » (drag vers la gauche) a un
2	// contour pointillé bleu qui défile en boucle, dans le même sens tout autour du rectangle
3	// (horaire), façon « rails de train ». Un `border` CSS classique ne sait pas animer un pointillé
4	// en boucle, et un unique élément avec 4 dégradés de fond en repeat-x/repeat-y déborde sur toute
5	// la surface plutôt que de rester sur les bords (chaque dégradé garde la taille de l'élément sur
6	// l'axe non répété) — on utilise donc 4 bandes fines, une par bord, chacune avec son propre
7	// dégradé tiled ; le sens de chaque bord est choisi pour que les 4 mis bout à bout tournent tous
8	// horaire (haut → droite, droite → bas, bas → gauche, gauche → haut).
9	@keyframes marchingAntsX {
10	  to { background-position: 8px 0; }
11	}
12	@keyframes marchingAntsXReverse {
13	  to { background-position: -8px 0; }
14	}
15	@keyframes marchingAntsY {
16	  to { background-position: 0 8px; }
17	}
18	@keyframes marchingAntsYReverse {
19	  to { background-position: 0 -8px; }
20	}
21	
22	$dash-color: #38bdf8; // bleu (accent), remplace le blanc précédent
23	
24	.crossingBox {
25	  position: absolute;
26	  inset: 0;
27	}
28	
29	.edgeX {
30	  position: absolute;
31	  left: 0;
32	  right: 0;
33	  height: 1px;
34	  background-image: linear-gradient(90deg, $dash-color 50%, transparent 50%);
35	  background-size: 8px 1px;
36	  background-repeat: repeat-x;
37	}
38	
39	.edgeY {
40	  position: absolute;
41	  top: 0;
42	  bottom: 0;
43	  width: 1px;
44	  background-image: linear-gradient(0deg, $dash-color 50%, transparent 50%);
45	  background-size: 1px 8px;
46	  background-repeat: repeat-y;
47	}
48	
49	.edgeTop { top: 0; animation: marchingAntsX 0.35s linear infinite; } // vers la droite
50	.edgeBottom { bottom: 0; animation: marchingAntsXReverse 0.35s linear infinite; } // vers la gauche
51	.edgeLeft { left: 0; animation: marchingAntsYReverse 0.35s linear infinite; } // vers le haut
52	.edgeRight { right: 0; animation: marchingAntsY 0.35s linear infinite; } // vers le bas
