1	import React, { useEffect, useState } from 'react';
2	import styles from './ModelStatusBox.module.scss';
3	import { Box, ChevronRight } from 'lucide-react';
4	import { motion, AnimatePresence } from 'framer-motion';
5	
6	interface SubMeshItem {
7	  id: string;
8	  name: string;
9	  color: string;
10	}
11	
12	interface ModelItem {
13	  id: string;
14	  name: string;
15	  children: SubMeshItem[];
16	}
17	
18	export const ModelStatusBox: React.FC = () => {
19	  const [models, setModels] = useState<ModelItem[]>([]);
20	  const [selectedModelName, setSelectedModelName] = useState<string | null>(null);
21	  const [selectedModelNames, setSelectedModelNames] = useState<Set<string>>(new Set());
22	  const [expandedModels, setExpandedModels] = useState<Record<string, boolean>>({});
23	  const [previewActive, setPreviewActive] = useState(false);
24	  // Le mode modélisation a sa propre arborescence (les corps) : celle des modèles importés
25	  // ferait doublon, on l'escamote comme en mode Prévisualisation.
26	  const [modelingActive, setModelingActive] = useState(false);
27	
28	  useEffect(() => {
29	    const handlePreviewToggled = (e: CustomEvent<{ active: boolean }>) => {
30	      setPreviewActive(!!e.detail?.active);
31	    };
32	    const handleModeChanged = (e: CustomEvent<{ mode: 'slicer' | 'modeling' }>) => {
33	      setModelingActive(e.detail?.mode === 'modeling');
34	    };
35	    window.addEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
36	    window.addEventListener('apex-mode-changed', handleModeChanged as EventListener);
37	    return () => {
38	      window.removeEventListener('apex-preview-toggled', handlePreviewToggled as EventListener);
39	      window.removeEventListener('apex-mode-changed', handleModeChanged as EventListener);
40	    };
41	  }, []);
42	
43	  useEffect(() => {
44	    const handleMeshSelected = (e: CustomEvent<{ name: string | null; names?: string[]; subMeshes?: SubMeshItem[] }>) => {
45	      setSelectedModelNames(new Set(e.detail?.names ?? (e.detail?.name ? [e.detail.name] : [])));
46	      if (e.detail?.name) {
47	        setSelectedModelName(e.detail.name);
48	        if (e.detail.subMeshes) {
49	          setModels(prev => {
50	            const exists = prev.some(m => m.name === e.detail.name);
51	            if (!exists) {
52	              return [...prev, {
53	                id: Date.now().toString(),
54	                name: e.detail.name!,
55	                children: e.detail.subMeshes!
56	              }];
57	            }
58	            return prev.map(m => m.name === e.detail.name ? { ...m, children: e.detail.subMeshes! } : m);
59	          });
60	        }
61	      } else {
62	        setSelectedModelName(null);
63	      }
64	    };
65	
66	    const handleImportModel = (e: CustomEvent<File>) => {
67	      if (e.detail) {
68	        const fileName = e.detail.name;
69	        setSelectedModelName(fileName);
70	      }
71	    };
72	
73	    const handleMeshDeleted = (e: CustomEvent<{ name?: string }>) => {
74	      const deletedName = e.detail?.name;
75	      if (deletedName) {
76	        setModels(prev => prev.filter(m => m.name !== deletedName));
77	        if (selectedModelName === deletedName) {
78	          setSelectedModelName(null);
79	        }
80	        setSelectedModelNames(prev => {
81	          const next = new Set(prev);
82	          next.delete(deletedName);
83	          return next;
84	        });
85	      } else {
86	        setModels([]);
87	        setSelectedModelName(null);
88	        setSelectedModelNames(new Set());
89	      }
90	    };
91	
92	    window.addEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
93	    window.addEventListener('apex-import-model', handleImportModel as EventListener);
94	    window.addEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
95	
96	    return () => {
97	      window.removeEventListener('apex-mesh-selected', handleMeshSelected as EventListener);
98	      window.removeEventListener('apex-import-model', handleImportModel as EventListener);
99	      window.removeEventListener('apex-mesh-deleted', handleMeshDeleted as EventListener);
100	    };
101	  }, [selectedModelName]);
102	
103	  const toggleExpand = (modelName: string, e: React.MouseEvent) => {
104	    e.stopPropagation();
105	    setExpandedModels(prev => ({
106	      ...prev,
107	      [modelName]: !prev[modelName]
108	    }));
109	  };
110	
111	  return (
112	    <div className={styles.container} data-apex-chrome-panel>
113	      <AnimatePresence>
114	        {!previewActive && !modelingActive && (
115	          <motion.div
116	            className={styles.toolbar}
117	            initial={{ opacity: 0, x: -20 }}
118	            animate={{ opacity: 1, x: 0 }}
119	            exit={{ opacity: 0, x: -20 }}
120	            transition={{
121	              opacity: { duration: 0.9, ease: 'linear' },
122	              x: { duration: 0.9, ease: 'easeInOut' },
123	            }}
124	          >
125	        <div className={styles.content}>
126	          {models.length === 0 ? (
127	            <motion.div 
128	              initial={{ opacity: 0 }} 
129	              animate={{ opacity: 1 }} 
130	              exit={{ opacity: 0 }} 
131	              className={styles.emptyText}
132	            >
133	              Aucun modèle sur le plateau
134	            </motion.div>
135	          ) : (
136	            <ul className={styles.treeList}>
137	              <AnimatePresence>
138	                {models.map((model) => {
139	                  const isSelected = selectedModelNames.has(model.name);
140	                  const isExpanded = !!expandedModels[model.name];
141	                  return (
142	                    <motion.li 
143	                      key={model.id} 
144	                      className={styles.treeNode}
145	                      initial={{ opacity: 0, height: 0, scale: 0.9 }}
146	                      animate={{ opacity: 1, height: 'auto', scale: 1 }}
147	                      exit={{ opacity: 0, height: 0, scale: 0.9, marginBottom: 0 }}
148	                      transition={{ duration: 0.25, ease: [0.16, 1, 0.3, 1] }}
149	                    >
150	                      <div 
151	                        className={`${styles.nodeRow} ${isSelected ? styles.selectedNode : ''}`}
152	                        onClick={(e) => {
153	                          setSelectedModelName(model.name);
154	                          window.dispatchEvent(new CustomEvent('apex-select-model', {
155	                            detail: { name: model.name, additive: e.ctrlKey || e.metaKey }
156	                          }));
157	                        }}
158	                      >
159	                        <button 
160	                          className="bg-transparent border-none cursor-pointer p-0 flex items-center justify-center text-zinc-400 hover:text-white transition-colors"
161	                          onClick={(e) => toggleExpand(model.name, e)}
162	                        >
163	                          <ChevronRight 
164	                            size={14} 
165	                            className={`transition-transform duration-200 ${isExpanded ? 'rotate-90' : ''}`} 
166	                          />
167	                        </button>
168	                        <Box size={14} className="text-[#00f0ff] ml-1" />
169	                        <span className={styles.nodeName}>{model.name}</span>
170	                      </div>
171	                      <AnimatePresence>
172	                        {isExpanded && model.children && model.children.length > 0 && (
173	                          <motion.ul 
174	                            className={styles.childList}
175	                            initial={{ opacity: 0, height: 0 }}
176	                            animate={{ opacity: 1, height: 'auto' }}
177	                            exit={{ opacity: 0, height: 0 }}
178	                            transition={{ duration: 0.2, ease: [0.16, 1, 0.3, 1] }}
179	                          >
180	                            {model.children.map(child => (
181	                              <li key={child.id} className={styles.childRow}>
182	                                <span 
183	                                  className="w-2.5 h-2.5 rounded-full shrink-0 mr-1.5 shadow-sm" 
184	                                  style={{ backgroundColor: child.color }} 
185	                                />
186	                                <span className={styles.childName}>{child.name}</span>
187	                              </li>
188	                            ))}
