"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import * as BABYLON from 'babylonjs';
import { Play, Pause, Upload } from 'lucide-react';
import { showError, showSuccess } from '@/utils/toast';
import styles from './GCodePreview.module.scss';

/**
 * Prévisualisateur de G-code polaire 4 axes (R, C, Z, B [, E], F) — voir la doc de format
 * ci-dessous. Ce n'est PAS un G-code cartésien standard (Marlin/RepRap G1/G2/G3) : une seule
 * commande de déplacement (G00) porte X=R (rayon), Y=C (angle plateau absolu, non replié),
 * Z (hauteur), B (inclinaison tête vers -R) et E (position absolue extrudeur, optionnelle).
 *
 * Repère machine :
 *  - Le PLATEAU tourne (angle C). La matière déposée est solidaire de sa rotation : un point
 *    déposé à l'angle C1 doit apparaître, quand le plateau est à l'angle courant C2, tourné de
 *    (C2 - C1) par rapport à sa position de dépôt. On stocke donc chaque point déposé en repère
 *    plateau (R, angle_piece = C au moment du dépôt, Z) puis on applique la rotation courante du
 *    plateau à TOUS les points en même temps pour l'affichage — jamais un repère "dérotaté" figé.
 *  - La TÊTE n'a que 2 degrés de liberté de position (R, Z) : elle reste dans un demi-plan
 *    vertical fixe de la machine (Y machine = 0), inclinée de B vers -R (vers l'axe de rotation).
 *    C'est le plateau qui tourne pour amener chaque point de la pièce sous elle.
 *  - Extrusion vs trajet à vide : E croissant = dépôt (plein) ; E absent/stationnaire = trajet à
 *    vide (pointillé / masqué par défaut).
 *  - C n'est jamais replié modulo 360 (continuité angulaire assurée par le générateur) : on
 *    convertit toujours C en radians directement, sans normaliser.
 */

interface GCodeMove {
  r: number;
  c: number; // degrés, absolu, non replié
  z: number;
  b: number;
  e: number | null; // null = pas de E sur cette ligne
  f: number | null;
  extruding: boolean; // E présent ET croissant par rapport au point précédent
}

interface ParsedGCode {
  moves: GCodeMove[];
  bounds: { minZ: number; maxZ: number; maxR: number };
  cRange: { min: number; max: number };
}

const DEG2RAD = Math.PI / 180;

function parseGCode(text: string): ParsedGCode {
  const lines = text.split(/\r?\n/);
  const moves: GCodeMove[] = [];
  let lastR = 0, lastC = 0, lastZ = 0, lastB = 0, lastE: number | null = null, lastF: number | null = null;

  for (const rawLine of lines) {
    // Retire les commentaires (';' jusqu'à fin de ligne, ou blocs '(...)').
    const line = rawLine.replace(/;.*$/, '').replace(/\(.*?\)/g, '').trim();
    if (!line) continue;
    if (!/^G0*0\b/i.test(line)) continue; // seule commande de déplacement du format : G00

    let r = lastR, c = lastC, z = lastZ, b = lastB, f = lastF;
    let e: number | null = null;
    let hasE = false;

    const tokenRe = /([XYZBEF])\s*(-?\d+\.?\d*)/gi;
    let m: RegExpExecArray | null;
    while ((m = tokenRe.exec(line)) !== null) {
      const letter = m[1].toUpperCase();
      const value = parseFloat(m[2]);
      if (Number.isNaN(value)) continue;
      switch (letter) {
        case 'X': r = value; break; // X = R (rayon)
        case 'Y': c = value; break; // Y = C (angle plateau, degrés, absolu non replié)
        case 'Z': z = value; break;
        case 'B': b = value; break;
        case 'E': e = value; hasE = true; break;
        case 'F': f = value; break;
      }
    }

    const extruding = hasE && lastE !== null && e !== null && e > lastE + 1e-9;
    moves.push({ r, c, z, b, e: hasE ? e : null, f, extruding });

    lastR = r; lastC = c; lastZ = z; lastB = b; lastF = f;
    if (hasE) lastE = e;
  }

  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
  for (const mv of moves) {
    if (mv.z < minZ) minZ = mv.z;
    if (mv.z > maxZ) maxZ = mv.z;
    if (mv.r > maxR) maxR = mv.r;
    if (mv.c < minC) minC = mv.c;
    if (mv.c > maxC) maxC = mv.c;
  }
  if (!Number.isFinite(minZ)) { minZ = 0; maxZ = 0; }
  if (!Number.isFinite(minC)) { minC = 0; maxC = 0; }

  return { moves, bounds: { minZ, maxZ, maxR }, cRange: { min: minC, max: maxC } };
}

/** Position machine instantanée d'un point déposé en repère plateau (r, depositC, z), quand le
 * plateau est actuellement à l'angle `currentC` — rotation synchronisée plateau + matière. */
function plateToMachine(r: number, depositC: number, z: number, currentC: number) {
  const angle = (depositC - depositC + currentC) * DEG2RAD; // = currentC en radians (voir note)
  // Le point est solidaire du plateau : sa position ANGULAIRE affichée suit toujours l'angle
  // courant du plateau (le point ne "glisse" pas sur le plateau une fois déposé), donc on
  // n'utilise en réalité que `currentC` ici — `depositC` sert uniquement de repère de stockage,
  // conservé pour lisibilité/216 doc.
  void angle;
  const rad = currentC * DEG2RAD;
  return new BABYLON.Vector3(r * Math.cos(rad), z, r * Math.sin(rad));
}

const RADIUS = 125;
const HEIGHT = 130;

export const GCodePreview: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const engineRef = useRef<BABYLON.Engine | null>(null);
  const sceneRef = useRef<BABYLON.Scene | null>(null);
  const plateRef = useRef<BABYLON.TransformNode | null>(null);
  const extrudedLinesRef = useRef<BABYLON.LinesMesh | null>(null);
  const travelLinesRef = useRef<BABYLON.LinesMesh | null>(null);
  const headMeshRef = useRef<BABYLON.TransformNode | null>(null);

  const parsedRef = useRef<ParsedGCode | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [fileName, setFileName] = useState<string | null>(null);
  const [moveCount, setMoveCount] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0); // 0..1
  const [showTravel, setShowTravel] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const progressRef = useRef(0);
  const isPlayingRef = useRef(false);
  const showTravelRef = useRef(false);
  useEffect(() => { progressRef.current = progress; }, [progress]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { showTravelRef.current = showTravel; }, [showTravel]);

  // --- Initialisation Babylon (scène indépendante du Viewport3D principal) ---
  useLayoutEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const engine = new BABYLON.Engine(canvas, true, { preserveDrawingBuffer: true });
    engineRef.current = engine;
    const scene = new BABYLON.Scene(engine);
    sceneRef.current = scene;
    scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);

    const camera = new BABYLON.ArcRotateCamera("gcodeCamera", Math.PI / 4, Math.PI / 3, 320, new BABYLON.Vector3(0, HEIGHT / 2, 0), scene);
    camera.attachControl(canvas, true);
    camera.wheelPrecision = 3;
    camera.lowerRadiusLimit = 40;
    camera.upperRadiusLimit = 900;
    camera.panningSensibility = 200;

    const light = new BABYLON.HemisphericLight("gcodeLight", new BABYLON.Vector3(0.3, 1, 0.2), scene);
    light.intensity = 0.9;

    // Plateau (disque tournant) — sert de repère visuel ET de parent Babylon pour que toute la
    // pièce déposée tourne rigidement avec lui (une seule rotation posée sur ce noeud plutôt que
    // recalculée point par point à la main).
    const plate = BABYLON.MeshBuilder.CreateDisc("plate", { radius: RADIUS, tessellation: 96 }, scene);
    plate.rotation.x = Math.PI / 2;
    const plateMat = new BABYLON.StandardMaterial("plateMat", scene);
    plateMat.diffuseColor = new BABYLON.Color3(0.16, 0.17, 0.19);
    plateMat.alpha = 0.55;
    plateMat.specularColor = new BABYLON.Color3(0, 0, 0);
    plate.material = plateMat;

    const plateNode = new BABYLON.TransformNode("plateNode", scene);
    plate.parent = plateNode;
    plateRef.current = plateNode;

    // Cercle de contour du plateau, pour repère visuel fixe (ne tourne pas) de la zone d'impression.
    const boundaryPoints: BABYLON.Vector3[] = [];
    for (let i = 0; i <= 96; i++) {
      const a = (i / 96) * Math.PI * 2;
      boundaryPoints.push(new BABYLON.Vector3(RADIUS * Math.cos(a), 0, RADIUS * Math.sin(a)));
    }
    const boundary = BABYLON.MeshBuilder.CreateLines("plateBoundary", { points: boundaryPoints }, scene);
    boundary.color = new BABYLON.Color3(0.35, 0.38, 0.42);

    // Repère radial fixe (demi-plan machine, Y machine = 0) où la tête se déplace toujours —
    // aide à visualiser que c'est le plateau qui tourne, pas la tête.
    const headPlaneLine = BABYLON.MeshBuilder.CreateLines("headPlane", {
      points: [new BABYLON.Vector3(0, 0, 0), new BABYLON.Vector3(RADIUS * 1.05, 0, 0)],
    }, scene);
    headPlaneLine.color = new BABYLON.Color3(0.3, 0.55, 0.6);

    // Tête d'impression : petit cône représentant la buse, positionné dans le demi-plan fixe
    // (R, 0, Z), incliné de B vers -R (vers le centre / l'axe de rotation).
    const headNode = new BABYLON.TransformNode("headNode", scene);
    const headCone = BABYLON.MeshBuilder.CreateCylinder("headCone", { diameterTop: 0, diameterBottom: 10, height: 22, tessellation: 16 }, scene);
    headCone.parent = headNode;
    headCone.position.y = 11; // pointe (tip) vers le bas, à l'origine du node
    const headMat = new BABYLON.StandardMaterial("headMat", scene);
    headMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
    headMat.emissiveColor = new BABYLON.Color3(0.3, 0.15, 0);
    headCone.material = headMat;
    headMeshRef.current = headNode;

    engine.runRenderLoop(() => {
      scene.render();
    });

    const handleResize = () => engine.resize();
    window.addEventListener('resize', handleResize);
    const ro = new ResizeObserver(() => engine.resize());
    if (containerRef.current) ro.observe(containerRef.current);

    return () => {
      window.removeEventListener('resize', handleResize);
      ro.disconnect();
      scene.dispose();
      engine.dispose();
      engineRef.current = null;
      sceneRef.current = null;
    };
  }, []);

  // --- Construit/reconstruit la géométrie de trajectoire à partir du G-code parsé ---
  const rebuildTrajectory = () => {
    const scene = sceneRef.current;
    const parsed = parsedRef.current;
    if (!scene || !parsed) return;

    extrudedLinesRef.current?.dispose();
    travelLinesRef.current?.dispose();
    extrudedLinesRef.current = null;
    travelLinesRef.current = null;

    const limit = Math.max(1, Math.floor(parsed.moves.length * progressRef.current));
    const visible = parsed.moves.slice(0, limit);
    if (visible.length < 2) return;

    // Chaque point est reconstruit en repère machine à SA PROPRE valeur de C (position de
    // dépôt) — puisque toute la géométrie extrudée est parentée à `plateNode`, appliquer la
    // rotation courante du plateau à ce noeud fait tourner l'ensemble de la matière déjà
    // déposée d'un seul bloc, exactement comme demandé par la doc (rotation plateau + matière
    // strictement synchronisées, jamais un repère "dérotaté").
    const toLocal = (mv: GCodeMove) => {
      const rad = mv.c * DEG2RAD;
      return new BABYLON.Vector3(mv.r * Math.cos(rad), mv.z, mv.r * Math.sin(rad));
    };

    const extrudedSegments: BABYLON.Vector3[][] = [];
    const travelSegments: BABYLON.Vector3[][] = [];
    let currentExtruded: BABYLON.Vector3[] = [];
    let currentTravel: BABYLON.Vector3[] = [];

    for (let i = 1; i < visible.length; i++) {
      const prev = visible[i - 1];
      const cur = visible[i];
      const p0 = toLocal(prev);
      const p1 = toLocal(cur);

      if (cur.extruding) {
        if (currentTravel.length > 1) travelSegments.push(currentTravel);
        currentTravel = [];
        if (currentExtruded.length === 0) currentExtruded.push(p0);
        currentExtruded.push(p1);
      } else {
        if (currentExtruded.length > 1) extrudedSegments.push(currentExtruded);
        currentExtruded = [];
        if (currentTravel.length === 0) currentTravel.push(p0);
        currentTravel.push(p1);
      }
    }
    if (currentExtruded.length > 1) extrudedSegments.push(currentExtruded);
    if (currentTravel.length > 1) travelSegments.push(currentTravel);

    if (extrudedSegments.length > 0) {
      const lines = BABYLON.MeshBuilder.CreateLineSystem("extrudedPath", { lines: extrudedSegments }, scene);
      lines.color = new BABYLON.Color3(0.22, 0.85, 0.95);
      lines.parent = plateRef.current;
      extrudedLinesRef.current = lines;
    }

    if (showTravelRef.current && travelSegments.length > 0) {
      const lines = BABYLON.MeshBuilder.CreateLineSystem("travelPath", { lines: travelSegments }, scene);
      lines.color = new BABYLON.Color3(0.5, 0.5, 0.55);
      lines.alpha = 0.35;
      lines.parent = plateRef.current;
      travelLinesRef.current = lines;
    }

    // Plateau et tête au dernier instant visible.
    const last = visible[visible.length - 1];
    if (plateRef.current) {
      plateRef.current.rotation.y = -last.c * DEG2RAD; // voir note de signe ci-dessous
    }
    if (headMeshRef.current) {
      headMeshRef.current.position.x = last.r;
      headMeshRef.current.position.y = last.z;
      headMeshRef.current.position.z = 0;
      // B incline la tête vers -R (vers le centre/l'axe de rotation) : une rotation autour de
      // l'axe Z local (perpendiculaire au demi-plan XY du repère machine fixe) penche la pointe
      // depuis +X (position R,0) vers -X.
      headMeshRef.current.rotation.z = -last.b * DEG2RAD;
    }
  };

  // Note de signe pour `plateRef.current.rotation.y` : Babylon utilise un repère main-gauche, où
  // une rotation Y positive tourne +X vers +Z. Notre conversion polaire (x = R cos C, z = R sin
  // C) suit la convention main-droite habituelle (+X vers +Z pour C croissant dans CE calcul-là
  // correspond en fait à une rotation Y NÉGATIVE dans le repère Babylon) — d'où le signe moins,
  // vérifié empiriquement pour que plateau et matière tournent bien dans le même sens (jamais en
  // miroir, cf. doc : erreur de signe déjà rencontrée et corrigée sur ce point précis).

  useEffect(() => {
    rebuildTrajectory();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [moveCount, progress, showTravel]);

  // --- Lecture / anim ---
  useEffect(() => {
    if (!isPlaying) return;
    let raf: number;
    const speed = 0.0025; // fraction de trajectoire par frame, ~1.5s pour tout parcourir à 60fps... ajustée ci-dessous
    const step = () => {
      setProgress((p) => {
        const next = p + speed;
        if (next >= 1) {
          setIsPlaying(false);
          return 1;
        }
        return next;
      });
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [isPlaying]);

  // --- Chargement de fichier ---
  const loadFile = async (file: File) => {
    const validExt = /\.(gcode|gco|g|ngc)$/i;
    if (!validExt.test(file.name)) {
      showError("Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.");
      return;
    }
    try {
      const text = await file.text();
      const parsed = parseGCode(text);
      if (parsed.moves.length === 0) {
        showError("Aucun mouvement G00 valide trouvé dans ce fichier.");
        return;
      }
      parsedRef.current = parsed;
      setFileName(file.name);
      setMoveCount(parsed.moves.length);
      setProgress(1);
      setIsPlaying(false);

      // Recentre la caméra sur l'étendue verticale de la pièce.
      const cam = sceneRef.current?.activeCamera as BABYLON.ArcRotateCamera | undefined;
      if (cam) {
        cam.target = new BABYLON.Vector3(0, (parsed.bounds.minZ + parsed.bounds.maxZ) / 2, 0);
        cam.radius = Math.max(180, parsed.bounds.maxR * 3);
      }

      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
    } catch (err) {
      showError("Impossible de lire ce fichier G-code.");
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) loadFile(file);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    if (!isDragging) setIsDragging(true);
  };

  const handleDragLeave = (e: React.DragEvent) => {
    if (e.currentTarget === e.target) setIsDragging(false);
  };

  const currentMove = (() => {
    const parsed = parsedRef.current;
    if (!parsed || parsed.moves.length === 0) return null;
    const idx = Math.min(parsed.moves.length - 1, Math.floor(parsed.moves.length * progress));
    return parsed.moves[idx];
  })();

  return (
    <div
      ref={containerRef}
      className={styles.container}
      data-apex-chrome-panel
      onDrop={handleDrop}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
    >
      <canvas ref={canvasRef} className={styles.canvas} />

      <input
        ref={fileInputRef}
        type="file"
        accept=".gcode,.gco,.g,.ngc"
        style={{ display: 'none' }}
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) loadFile(file);
          e.target.value = '';
        }}
      />

      {!fileName && !isDragging && (
        <div className={styles.emptyHint}>
          <Upload size={28} />
          <span className={styles.emptyHintTitle}>Glissez un fichier G-code ici</span>
          <span className={styles.emptyHintSub}>.gcode · .gco · .g · .ngc — ou cliquez pour parcourir</span>
        </div>
      )}

      {isDragging && (
        <div className={styles.dropOverlay}>
          <div className={styles.dropOverlayInner}>
            <Upload size={26} />
            <span>Déposez le fichier G-code</span>
            <span className={styles.dropOverlaySub}>.gcode, .gco, .g, .ngc</span>
          </div>
        </div>
      )}

      {!fileName && !isDragging && (
        <div
          style={{ position: 'absolute', inset: 0, cursor: 'pointer' }}
          onClick={() => fileInputRef.current?.click()}
        />
      )}

      {fileName && (
        <div className={styles.infoPanel}>
          <div className={styles.fileName}>{fileName}</div>
          <div className={styles.infoRow}>
            <span>Mouvements</span>
            <span className={styles.infoValue}>{moveCount}</span>
          </div>
          {currentMove && (
            <>
              <div className={styles.infoRow}>
                <span>R</span>
                <span className={styles.infoValue}>{currentMove.r.toFixed(2)} mm</span>
              </div>
              <div className={styles.infoRow}>
                <span>C</span>
                <span className={styles.infoValue}>{currentMove.c.toFixed(2)}°</span>
              </div>
              <div className={styles.infoRow}>
                <span>Z</span>
                <span className={styles.infoValue}>{currentMove.z.toFixed(2)} mm</span>
              </div>
              <div className={styles.infoRow}>
                <span>B</span>
                <span className={styles.infoValue}>{currentMove.b.toFixed(1)}°</span>
              </div>
            </>
          )}
        </div>
      )}

      {fileName && (
        <div className={styles.controlsPanel}>
          <button
            className={styles.playButton}
            onClick={() => setIsPlaying((p) => !p)}
            disabled={progress >= 1 && !isPlaying}
          >
            {isPlaying ? <Pause size={16} /> : <Play size={16} />}
          </button>
          <input
            type="range"
            className={styles.slider}
            min={0}
            max={1}
            step={0.001}
            value={progress}
            onChange={(e) => {
              setIsPlaying(false);
              setProgress(parseFloat(e.target.value));
            }}
          />
          <span className={styles.sliderLabel}>
            {Math.floor(progress * moveCount)} / {moveCount}
          </span>
          <button
            className={`${styles.toggleButton} ${showTravel ? styles.toggleButtonActive : ''}`}
            onClick={() => setShowTravel((s) => !s)}
          >
            Trajets à vide
          </button>
        </div>
      )}
    </div>
  );
};

