"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import * as BABYLON from 'babylonjs';
import { Play, Pause, Upload, FileCode2 } from 'lucide-react';
import { showError, showSuccess, showWarning } from '@/utils/toast';
import styles from './GCodePreview.module.scss';

/**
 * Prévisualisateur du G-code polaire 4 axes de l'Apex. Ce n'est PAS un G-code cartésien de
 * slicer classique : une seule commande de déplacement, `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
 *
 *  - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
 *  - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
 *    la continuité angulaire, un C > 360 ou négatif est normal).
 *  - Z : hauteur (mm). B : inclinaison de la tête vers −R (vers l'axe de rotation), en degrés.
 *  - E (optionnel) : position absolue de l'extrudeur. E croissant = dépôt ; E absent ou
 *    stationnaire = trajet à vide.
 *
 * Représentation :
 *  - La matière est stockée une fois pour toutes en repère plateau (x = R cos C, z = R sin C,
 *    avec le C du moment du dépôt) et parentée au même noeud que le disque du plateau : une
 *    seule rotation posée sur ce noeud fait tourner plateau et matière strictement ensemble.
 *  - La tête reste dans le demi-plan machine fixe (R, 0, Z) ; c'est le plateau qui tourne pour
 *    amener la pièce sous elle. Les valeurs R/Z sont déjà compensées du pivot par le
 *    générateur (`--pivot`) : on les affiche telles quelles.
 *  - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
 *    segments sont subdivisés en angle pour suivre l'arc réellement parcouru, et la position
 *    animée entre deux consignes est interpolée en (R, C, Z, B) puis convertie.
 *  - Aucune décimation "1 point sur N" (sauts angulaires visibles sur les portions courbes).
 */

interface GCodeMove {
  r: number;
  c: number;
  z: number;
  b: number;
  extruding: boolean;
}

interface ParsedGCode {
  moves: GCodeMove[];
  minZ: number;
  maxZ: number;
  maxR: number;
  minC: number;
  maxC: number;
  extrudingCount: number;
}

/** Index de dessin d'un mouvement (segment de moves[k-1] à moves[k]) dans son LinesMesh. */
interface MoveDraw {
  segments: number; // nombre de sous-segments après subdivision angulaire
}

const DEG2RAD = Math.PI / 180;
const PLATE_RADIUS = 125;
const PLATE_HEIGHT = 130;
// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
const MAX_SUBSEGMENT_DEG = 0.5;
// Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
// boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite).
const SUSPICIOUS_C_RANGE_DEG = 720;
const SPEED_OPTIONS = [25, 100, 400, 1600, 6400]; // mouvements par seconde

const G00_RE = /^G0*0(?![0-9])/i;
const WORD_RE = /([XYZBEF])\s*([-+]?(?:\d+\.?\d*|\.\d+))/gi;

function parseGCode(text: string): ParsedGCode {
  const moves: GCodeMove[] = [];
  let r = 0, c = 0, z = 0, b = 0;
  let lastE: number | null = null;
  let extrudingCount = 0;

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
    if (!line || !G00_RE.test(line)) continue;

    let e: number | null = null;
    WORD_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = WORD_RE.exec(line)) !== null) {
      const value = parseFloat(m[2]);
      if (Number.isNaN(value)) continue;
      switch (m[1].toUpperCase()) {
        case 'X': r = value; break;
        case 'Y': c = value; break;
        case 'Z': z = value; break;
        case 'B': b = value; break;
        case 'E': e = value; break;
      }
    }

    const extruding = e !== null && lastE !== null && e > lastE + 1e-9;
    if (e !== null) lastE = e;
    if (extruding) extrudingCount++;
    moves.push({ r, c, z, b, extruding });
  }

  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
  for (const mv of moves) {
    if (mv.z < minZ) minZ = mv.z;
    if (mv.z > maxZ) maxZ = mv.z;
    if (mv.r > maxR) maxR = mv.r;
    if (mv.c < minC) minC = mv.c;
    if (mv.c > maxC) maxC = mv.c;
  }
  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }

  return { moves, minZ, maxZ, maxR, minC, maxC, extrudingCount };
}

/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
 * en index de mouvement fractionnaire. */
function stateAt(moves: GCodeMove[], t: number) {
  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
  const a = moves[i];
  const bMove = moves[Math.min(moves.length - 1, i + 1)];
  const f = Math.max(0, Math.min(1, t - i));
  return {
    r: a.r + (bMove.r - a.r) * f,
    c: a.c + (bMove.c - a.c) * f,
    z: a.z + (bMove.z - a.z) * f,
    b: a.b + (bMove.b - a.b) * f,
  };
}

function subdivisions(a: GCodeMove, b: GCodeMove) {
  return Math.max(1, Math.ceil(Math.abs(b.c - a.c) / MAX_SUBSEGMENT_DEG));
}

/** Construit un LinesMesh (repère plateau) contenant tous les mouvements dont `extruding`
 * vaut `wantExtruding`, dans l'ordre du fichier. Renvoie aussi, pour chaque mouvement, le
 * nombre cumulé d'indices à dessiner une fois ce mouvement terminé — ce qui permet d'afficher
 * n'importe quel préfixe de la trajectoire en changeant simplement `indexCount`, sans jamais
 * reconstruire la géométrie. */
function buildPathMesh(
  name: string,
  parsed: ParsedGCode,
  draws: MoveDraw[],
  wantExtruding: boolean,
  colorAt: (z: number) => BABYLON.Color4,
  scene: BABYLON.Scene,
) {
  const { moves } = parsed;
  let vertexTotal = 0;
  for (let k = 1; k < moves.length; k++) {
    if (moves[k].extruding === wantExtruding) vertexTotal += draws[k].segments + 1;
  }

  const cumIndices = new Uint32Array(moves.length);
  if (vertexTotal === 0) return { mesh: null, cumIndices };

  const positions = new Float32Array(vertexTotal * 3);
  const colors = new Float32Array(vertexTotal * 4);
  const indices = new Uint32Array((vertexTotal - 1) * 2);
  let v = 0;
  let idx = 0;

  for (let k = 1; k < moves.length; k++) {
    const cur = moves[k];
    if (cur.extruding === wantExtruding) {
      const prev = moves[k - 1];
      const n = draws[k].segments;
      for (let s = 0; s <= n; s++) {
        const f = s / n;
        const r = prev.r + (cur.r - prev.r) * f;
        const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
        const z = prev.z + (cur.z - prev.z) * f;
        positions[v * 3] = r * Math.cos(c);
        positions[v * 3 + 1] = z;
        positions[v * 3 + 2] = r * Math.sin(c);
        const col = colorAt(z);
        colors[v * 4] = col.r;
        colors[v * 4 + 1] = col.g;
        colors[v * 4 + 2] = col.b;
        colors[v * 4 + 3] = col.a;
        if (s > 0) {
          indices[idx++] = v - 1;
          indices[idx++] = v;
        }
        v++;
      }
    }
    cumIndices[k] = idx;
  }

  const mesh = new BABYLON.LinesMesh(name, scene, null, null, undefined, true, true);
  const data = new BABYLON.VertexData();
  data.positions = positions;
  data.colors = colors;
  data.indices = indices.subarray(0, idx);
  data.applyToMesh(mesh);
  mesh.isPickable = false;
  mesh.alwaysSelectAsActiveMesh = true;
  return { mesh, cumIndices };
}

export const GCodePreview: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sceneRef = useRef<BABYLON.Scene | null>(null);
  const cameraRef = useRef<BABYLON.ArcRotateCamera | null>(null);
  const plateNodeRef = useRef<BABYLON.TransformNode | null>(null);
  const headNodeRef = useRef<BABYLON.TransformNode | null>(null);

  // Données de trajectoire : refs (pas de state) — lues à chaque frame par la boucle de rendu.
  const parsedRef = useRef<ParsedGCode | null>(null);
  const drawsRef = useRef<MoveDraw[]>([]);
  const extrudedRef = useRef<{ mesh: BABYLON.LinesMesh | null; cumIndices: Uint32Array } | null>(null);
  const travelRef = useRef<{ mesh: BABYLON.LinesMesh | null; cumIndices: Uint32Array } | null>(null);
  const tRef = useRef(0); // position de lecture, en index de mouvement fractionnaire
  const playingRef = useRef(false);
  const speedRef = useRef(SPEED_OPTIONS[1]);
  const showTravelRef = useRef(false);

  const dragDepthRef = useRef(0);
  const [isDragging, setIsDragging] = useState(false);
  const [fileInfo, setFileInfo] = useState<{ name: string; moves: number; extruding: number; minZ: number; maxZ: number; minC: number; maxC: number } | null>(null);
  const [t, setT] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(SPEED_OPTIONS[1]);
  const [showTravel, setShowTravel] = useState(false);

  useEffect(() => { playingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { speedRef.current = speed; }, [speed]);
  useEffect(() => {
    showTravelRef.current = showTravel;
    travelRef.current?.mesh?.setEnabled(showTravel);
  }, [showTravel]);

  useLayoutEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const engine = new BABYLON.Engine(canvas, true, { preserveDrawingBuffer: true });
    const scene = new BABYLON.Scene(engine);
    sceneRef.current = scene;
    // Fond opaque : Viewport3D reste monté juste dessous et ne doit pas transparaître.
    scene.clearColor = new BABYLON.Color4(0.165, 0.176, 0.204, 1);

    const camera = new BABYLON.ArcRotateCamera('gcodeCamera', -Math.PI / 3, Math.PI / 3, 320, new BABYLON.Vector3(0, 20, 0), scene);
    camera.attachControl(canvas, true);
    camera.wheelPrecision = 3;
    camera.lowerRadiusLimit = 20;
    camera.upperRadiusLimit = 1200;
    camera.panningSensibility = 200;
    camera.minZ = 0.5;
    cameraRef.current = camera;

    const light = new BABYLON.HemisphericLight('gcodeLight', new BABYLON.Vector3(0.3, 1, 0.2), scene);
    light.intensity = 0.9;

    // Noeud du plateau : le disque, ses repères ET toute la matière déposée en sont enfants,
    // pour qu'une unique rotation les fasse tourner de façon strictement synchronisée.
    const plateNode = new BABYLON.TransformNode('plateNode', scene);
    plateNodeRef.current = plateNode;

    const plate = BABYLON.MeshBuilder.CreateDisc('plate', { radius: PLATE_RADIUS, tessellation: 128, sideOrientation: BABYLON.Mesh.DOUBLESIDE }, scene);
    plate.rotation.x = Math.PI / 2;
    plate.position.y = -0.05;
    plate.isPickable = false;
    const plateMat = new BABYLON.StandardMaterial('plateMat', scene);
    plateMat.diffuseColor = new BABYLON.Color3(0.2, 0.21, 0.24);
    plateMat.specularColor = BABYLON.Color3.Black();
    plate.material = plateMat;
    plate.parent = plateNode;

    // Repères du plateau (rayons + cercles) : sans eux la rotation d'un disque uni est invisible.
    const plateMarks: BABYLON.Vector3[][] = [];
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      plateMarks.push([
        new BABYLON.Vector3(20 * Math.cos(a), 0, 20 * Math.sin(a)),
        new BABYLON.Vector3(PLATE_RADIUS * Math.cos(a), 0, PLATE_RADIUS * Math.sin(a)),
      ]);
    }
    for (const radius of [25, 50, 75, 100, PLATE_RADIUS]) {
      const ring: BABYLON.Vector3[] = [];
      for (let i = 0; i <= 128; i++) {
        const a = (i / 128) * Math.PI * 2;
        ring.push(new BABYLON.Vector3(radius * Math.cos(a), 0, radius * Math.sin(a)));
      }
      plateMarks.push(ring);
    }
    const marks = BABYLON.MeshBuilder.CreateLineSystem('plateMarks', { lines: plateMarks }, scene);
    marks.color = new BABYLON.Color3(0.34, 0.37, 0.42);
    marks.isPickable = false;
    marks.parent = plateNode;

    // Repère angulaire 0° du plateau, coloré, pour lire la valeur courante de C d'un coup d'oeil.
    const zeroMark = BABYLON.MeshBuilder.CreateLines('plateZero', {
      points: [new BABYLON.Vector3(PLATE_RADIUS - 12, 0.05, 0), new BABYLON.Vector3(PLATE_RADIUS, 0.05, 0)],
    }, scene);
    zeroMark.color = new BABYLON.Color3(1, 0.55, 0.05);
    zeroMark.parent = plateNode;

    // Demi-plan machine fixe (Y machine = 0, côté +R) dans lequel la tête se déplace.
    const headPlane = BABYLON.MeshBuilder.CreateLines('headPlane', {
      points: [
        new BABYLON.Vector3(0, 0.1, 0),
        new BABYLON.Vector3(PLATE_RADIUS + 10, 0.1, 0),
        new BABYLON.Vector3(PLATE_RADIUS + 10, PLATE_HEIGHT, 0),
        new BABYLON.Vector3(0, PLATE_HEIGHT, 0),
      ],
    }, scene);
    headPlane.color = new BABYLON.Color3(0.25, 0.5, 0.58);
    headPlane.alpha = 0.5;
    headPlane.isPickable = false;

    // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le
    // noeud est ensuite orienté pour que ce corps penche de B vers −R.
    const headNode = new BABYLON.TransformNode('headNode', scene);
    headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
    const headMat = new BABYLON.StandardMaterial('headMat', scene);
    headMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
    headMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
    const nozzle = BABYLON.MeshBuilder.CreateCylinder('headNozzle', { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
    nozzle.position.y = 4.5;
    nozzle.material = headMat;
    nozzle.parent = headNode;
    const body = BABYLON.MeshBuilder.CreateCylinder('headBody', { diameter: 14, height: 26, tessellation: 24 }, scene);
    body.position.y = 9 + 13;
    const bodyMat = new BABYLON.StandardMaterial('headBodyMat', scene);
    bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
    bodyMat.alpha = 0.55;
    body.material = bodyMat;
    body.parent = headNode;
    for (const mesh of [nozzle, body]) mesh.isPickable = false;
    headNode.setEnabled(false);
    headNodeRef.current = headNode;

    const up = BABYLON.Vector3.Up();
    const headDir = new BABYLON.Vector3();
    let uiSyncAccumulator = 0;

    scene.onBeforeRenderObservable.add(() => {
      const parsed = parsedRef.current;
      if (!parsed || parsed.moves.length === 0) return;
      const last = parsed.moves.length - 1;

      if (playingRef.current) {
        const dt = engine.getDeltaTime() / 1000;
        tRef.current = Math.min(last, tRef.current + speedRef.current * dt);
        uiSyncAccumulator += dt;
        if (tRef.current >= last) {
          playingRef.current = false;
          setIsPlaying(false);
          setT(last);
        } else if (uiSyncAccumulator > 1 / 20) {
          uiSyncAccumulator = 0;
          setT(tRef.current);
        }
      }

      const tt = tRef.current;
      const state = stateAt(parsed.moves, tt);

      // Rotation du plateau (et donc de la matière qui en est enfant). Dans le repère main
      // gauche de Babylon, rotation.y = ψ envoie un angle local θ (x = cos θ, z = sin θ) sur
      // θ − ψ. Avec ψ = C courant, un point déposé à C_dépôt se trouve à l'angle machine
      // C_dépôt − C : pile sous la tête (angle 0) au moment de son dépôt, puis entraîné avec
      // le plateau. Le signe opposé ferait apparaître la pièce en miroir.
      if (plateNodeRef.current) plateNodeRef.current.rotation.y = state.c * DEG2RAD;

      headNode.position.set(state.r, state.z, 0);
      const bRad = state.b * DEG2RAD;
      headDir.set(-Math.sin(bRad), Math.cos(bRad), 0);
      BABYLON.Quaternion.FromUnitVectorsToRef(up, headDir, headNode.rotationQuaternion!);

      // Préfixe de trajectoire affiché : mouvements terminés + fraction du mouvement en cours
      // (au sous-segment près, cohérent avec l'interpolation en C).
      const i = Math.floor(tt);
      const frac = tt - i;
      const next = Math.min(last, i + 1);
      const partialSegs = next > i ? Math.floor(frac * drawsRef.current[next].segments) * 2 : 0;
      for (const [entry, wantExtruding] of [[extrudedRef.current, true], [travelRef.current, false]] as const) {
        if (!entry?.mesh) continue;
        let count = entry.cumIndices[i];
        if (next > i && parsed.moves[next].extruding === wantExtruding) count += partialSegs;
        const sub = entry.mesh.subMeshes?.[0];
        if (sub) sub.indexCount = count;
        entry.mesh.isVisible = count > 0;
      }
    });

    engine.runRenderLoop(() => scene.render());

    const ro = new ResizeObserver(() => engine.resize());
    if (containerRef.current) ro.observe(containerRef.current);

    return () => {
      ro.disconnect();
      scene.dispose();
      engine.dispose();
      sceneRef.current = null;
      cameraRef.current = null;
      plateNodeRef.current = null;
      headNodeRef.current = null;
      extrudedRef.current = null;
      travelRef.current = null;
    };
  }, []);

  const loadFile = async (file: File) => {
    if (!/\.(gcode|gco|g|ngc)$/i.test(file.name)) {
      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
      return;
    }
    const scene = sceneRef.current;
    if (!scene) return;

    let parsed: ParsedGCode;
    try {
      parsed = parseGCode(await file.text());
    } catch {
      showError('Impossible de lire ce fichier G-code.');
      return;
    }
    if (parsed.moves.length < 2) {
      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
      return;
    }

    extrudedRef.current?.mesh?.dispose();
    travelRef.current?.mesh?.dispose();

    const draws: MoveDraw[] = parsed.moves.map((mv, k) => ({
      segments: k === 0 ? 0 : subdivisions(parsed.moves[k - 1], mv),
    }));

    const zSpan = Math.max(1e-6, parsed.maxZ - parsed.minZ);
    const low = new BABYLON.Color3(0.12, 0.42, 1);
    const high = new BABYLON.Color3(0.3, 0.95, 0.9);
    const extrudedColor = (z: number) => {
      const c = BABYLON.Color3.Lerp(low, high, (z - parsed.minZ) / zSpan);
      return new BABYLON.Color4(c.r, c.g, c.b, 1);
    };
    const travelColor = () => new BABYLON.Color4(0.75, 0.75, 0.8, 0.35);

    const extruded = buildPathMesh('extrudedPath', parsed, draws, true, extrudedColor, scene);
    const travel = buildPathMesh('travelPath', parsed, draws, false, travelColor, scene);
    extruded.mesh && (extruded.mesh.parent = plateNodeRef.current);
    if (travel.mesh) {
      travel.mesh.parent = plateNodeRef.current;
      travel.mesh.setEnabled(showTravelRef.current);
    }

    parsedRef.current = parsed;
    drawsRef.current = draws;
    extrudedRef.current = extruded;
    travelRef.current = travel;

    const last = parsed.moves.length - 1;
    tRef.current = last;
    playingRef.current = false;
    setIsPlaying(false);
    setT(last);
    headNodeRef.current?.setEnabled(true);

    const camera = cameraRef.current;
    if (camera) {
      camera.setTarget(new BABYLON.Vector3(0, (parsed.minZ + parsed.maxZ) / 2, 0));
      camera.radius = Math.max(120, Math.max(parsed.maxR, parsed.maxZ - parsed.minZ) * 3.2);
    }

    setFileInfo({
      name: file.name,
      moves: parsed.moves.length,
      extruding: parsed.extrudingCount,
      minZ: parsed.minZ,
      maxZ: parsed.maxZ,
      minC: parsed.minC,
      maxC: parsed.maxC,
    });

    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
    } else {
      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
    }
  };

  const seek = (value: number) => {
    playingRef.current = false;
    setIsPlaying(false);
    tRef.current = value;
    setT(value);
  };

  const togglePlay = () => {
    const parsed = parsedRef.current;
    if (!parsed) return;
    if (!isPlaying && tRef.current >= parsed.moves.length - 1) {
      tRef.current = 0;
      setT(0);
    }
    playingRef.current = !isPlaying;
    setIsPlaying(!isPlaying);
  };

  // Compteur d'entrées/sorties : `dragleave` se déclenche aussi en survolant un enfant.
  const handleDragEnter = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('Files')) return;
    e.preventDefault();
    dragDepthRef.current++;
    setIsDragging(true);
  };
  const handleDragOver = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('Files')) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };
  const handleDragLeave = () => {
    dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
    if (dragDepthRef.current === 0) setIsDragging(false);
  };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    dragDepthRef.current = 0;
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) loadFile(file);
  };

  const parsed = parsedRef.current;
  const current = parsed && parsed.moves.length ? stateAt(parsed.moves, t) : null;
  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;

  return (
    <div
      ref={containerRef}
      className={styles.container}
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <canvas ref={canvasRef} className={styles.canvas} />

      <input
        ref={fileInputRef}
        type="file"
        accept=".gcode,.gco,.g,.ngc"
        style={{ display: 'none' }}
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) loadFile(file);
          e.target.value = '';
        }}
      />

      {!fileInfo && !isDragging && (
        <button type="button" className={styles.emptyHint} onClick={() => fileInputRef.current?.click()}>
          <Upload size={28} />
          <span className={styles.emptyHintTitle}>Glissez un fichier G-code ici</span>
          <span className={styles.emptyHintSub}>.gcode · .gco · .g · .ngc — ou cliquez pour parcourir</span>
        </button>
      )}

      {isDragging && (
        <div className={styles.dropOverlay}>
          <div className={styles.dropOverlayInner}>
            <Upload size={26} />
            <span>Déposez le fichier G-code</span>
            <span className={styles.dropOverlaySub}>.gcode, .gco, .g, .ngc</span>
          </div>
        </div>
      )}

      {fileInfo && current && (
        <div className={styles.infoPanel} data-apex-chrome-panel>
          <div className={styles.fileName}>
            <FileCode2 size={14} />
            <span>{fileInfo.name}</span>
          </div>
          <div className={styles.infoRow}><span>Mouvements</span><span className={styles.infoValue}>{fileInfo.moves.toLocaleString('fr-FR')}</span></div>
          <div className={styles.infoRow}><span>Dont extrusion</span><span className={styles.infoValue}>{fileInfo.extruding.toLocaleString('fr-FR')}</span></div>
          <div className={styles.infoRow}><span>Hauteur</span><span className={styles.infoValue}>{fileInfo.minZ.toFixed(2)} → {fileInfo.maxZ.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>Plage C</span><span className={styles.infoValue}>{fileInfo.minC.toFixed(1)}° → {fileInfo.maxC.toFixed(1)}°</span></div>
          <div className={styles.infoDivider} />
          <div className={styles.infoRow}><span>R</span><span className={styles.infoValue}>{current.r.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>C</span><span className={styles.infoValue}>{current.c.toFixed(2)}°</span></div>
          <div className={styles.infoRow}><span>Z</span><span className={styles.infoValue}>{current.z.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>B</span><span className={styles.infoValue}>{current.b.toFixed(1)}°</span></div>
          <div className={styles.infoRow}>
            <span>Segment</span>
            <span className={currentMove?.extruding ? styles.badgeExtrude : styles.badgeTravel}>
              {currentMove?.extruding ? 'Extrusion' : 'Trajet à vide'}
            </span>
          </div>
          <button type="button" className={styles.linkButton} onClick={() => fileInputRef.current?.click()}>
            Ouvrir un autre fichier…
          </button>
        </div>
      )}

      {fileInfo && (
        <div className={styles.controlsPanel} data-apex-chrome-panel>
          <button type="button" className={styles.playButton} onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Lecture'}>
            {isPlaying ? <Pause size={16} /> : <Play size={16} />}
          </button>
          <input
            type="range"
            className={styles.slider}
            min={0}
            max={lastIndex}
            step={0.01}
            value={t}
            onChange={(e) => seek(parseFloat(e.target.value))}
          />
          <span className={styles.sliderLabel}>
            {Math.floor(t).toLocaleString('fr-FR')} / {lastIndex.toLocaleString('fr-FR')}
          </span>
          <select
            className={styles.speedSelect}
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
            aria-label="Vitesse de lecture"
          >
            {SPEED_OPTIONS.map((s) => (
              <option key={s} value={s}>{s} mvt/s</option>
            ))}
          </select>
          <button
            type="button"
            className={`${styles.toggleButton} ${showTravel ? styles.toggleButtonActive : ''}`}
            onClick={() => setShowTravel((s) => !s)}
          >
            Trajets à vide
          </button>
        </div>
      )}
    </div>
  );
};

toolUseResult.content:
"use client";

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import * as BABYLON from 'babylonjs';
import { Play, Pause, Upload, FileCode2 } from 'lucide-react';
import { showError, showSuccess, showWarning } from '@/utils/toast';
import styles from './GCodePreview.module.scss';

/**
 * Prévisualisateur du G-code polaire 4 axes de l'Apex. Ce n'est PAS un G-code cartésien de
 * slicer classique : une seule commande de déplacement, `G00 Y<C> X<R> Z<Z> B<B> [E<e>] F<f>`.
 *
 *  - X = R : rayon depuis le centre du plateau (mm, ≥ 0).
 *  - Y = C : angle du plateau (degrés, absolu, JAMAIS replié modulo 360 — le générateur garde
 *    la continuité angulaire, un C > 360 ou négatif est normal).
 *  - Z : hauteur (mm). B : inclinaison de la tête vers −R (vers l'axe de rotation), en degrés.
 *  - E (optionnel) : position absolue de l'extrudeur. E croissant = dépôt ; E absent ou
 *    stationnaire = trajet à vide.
 *
 * Représentation :
 *  - La matière est stockée une fois pour toutes en repère plateau (x = R cos C, z = R sin C,
 *    avec le C du moment du dépôt) et parentée au même noeud que le disque du plateau : une
 *    seule rotation posée sur ce noeud fait tourner plateau et matière strictement ensemble.
 *  - La tête reste dans le demi-plan machine fixe (R, 0, Z) ; c'est le plateau qui tourne pour
 *    amener la pièce sous elle. Les valeurs R/Z sont déjà compensées du pivot par le
 *    générateur (`--pivot`) : on les affiche telles quelles.
 *  - Tout est interpolé dans l'espace (R, C, Z, B) du firmware, jamais en cartésien : les
 *    segments sont subdivisés en angle pour suivre l'arc réellement parcouru, et la position
 *    animée entre deux consignes est interpolée en (R, C, Z, B) puis convertie.
 *  - Aucune décimation "1 point sur N" (sauts angulaires visibles sur les portions courbes).
 */

interface GCodeMove {
  r: number;
  c: number;
  z: number;
  b: number;
  extruding: boolean;
}

interface ParsedGCode {
  moves: GCodeMove[];
  minZ: number;
  maxZ: number;
  maxR: number;
  minC: number;
  maxC: number;
  extrudingCount: number;
}

/** Index de dessin d'un mouvement (segment de moves[k-1] à moves[k]) dans son LinesMesh. */
interface MoveDraw {
  segments: number; // nombre de sous-segments après subdivision angulaire
}

const DEG2RAD = Math.PI / 180;
const PLATE_RADIUS = 125;
const PLATE_HEIGHT = 130;
// Pas angulaire max d'un sous-segment : au-delà, la corde cartésienne s'écarte visiblement de
// l'arc réellement décrit par le firmware (qui interpole en C, pas en x/y).
const MAX_SUBSEGMENT_DEG = 0.5;
// Au-delà de cette amplitude totale de C, le fichier vient très probablement de la version
// boguée du générateur (C qui dérive de tour en tour au lieu d'osciller dans une plage étroite).
const SUSPICIOUS_C_RANGE_DEG = 720;
const SPEED_OPTIONS = [25, 100, 400, 1600, 6400]; // mouvements par seconde

const G00_RE = /^G0*0(?![0-9])/i;
const WORD_RE = /([XYZBEF])\s*([-+]?(?:\d+\.?\d*|\.\d+))/gi;

function parseGCode(text: string): ParsedGCode {
  const moves: GCodeMove[] = [];
  let r = 0, c = 0, z = 0, b = 0;
  let lastE: number | null = null;
  let extrudingCount = 0;

  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.replace(/\(.*?\)/g, '').replace(/;.*$/, '').trim();
    if (!line || !G00_RE.test(line)) continue;

    let e: number | null = null;
    WORD_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = WORD_RE.exec(line)) !== null) {
      const value = parseFloat(m[2]);
      if (Number.isNaN(value)) continue;
      switch (m[1].toUpperCase()) {
        case 'X': r = value; break;
        case 'Y': c = value; break;
        case 'Z': z = value; break;
        case 'B': b = value; break;
        case 'E': e = value; break;
      }
    }

    const extruding = e !== null && lastE !== null && e > lastE + 1e-9;
    if (e !== null) lastE = e;
    if (extruding) extrudingCount++;
    moves.push({ r, c, z, b, extruding });
  }

  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
  for (const mv of moves) {
    if (mv.z < minZ) minZ = mv.z;
    if (mv.z > maxZ) maxZ = mv.z;
    if (mv.r > maxR) maxR = mv.r;
    if (mv.c < minC) minC = mv.c;
    if (mv.c > maxC) maxC = mv.c;
  }
  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }

  return { moves, minZ, maxZ, maxR, minC, maxC, extrudingCount };
}

/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
 * en index de mouvement fractionnaire. */
function stateAt(moves: GCodeMove[], t: number) {
  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
  const a = moves[i];
  const bMove = moves[Math.min(moves.length - 1, i + 1)];
  const f = Math.max(0, Math.min(1, t - i));
  return {
    r: a.r + (bMove.r - a.r) * f,
    c: a.c + (bMove.c - a.c) * f,
    z: a.z + (bMove.z - a.z) * f,
    b: a.b + (bMove.b - a.b) * f,
  };
}

function subdivisions(a: GCodeMove, b: GCodeMove) {
  return Math.max(1, Math.ceil(Math.abs(b.c - a.c) / MAX_SUBSEGMENT_DEG));
}

/** Construit un LinesMesh (repère plateau) contenant tous les mouvements dont `extruding`
 * vaut `wantExtruding`, dans l'ordre du fichier. Renvoie aussi, pour chaque mouvement, le
 * nombre cumulé d'indices à dessiner une fois ce mouvement terminé — ce qui permet d'afficher
 * n'importe quel préfixe de la trajectoire en changeant simplement `indexCount`, sans jamais
 * reconstruire la géométrie. */
function buildPathMesh(
  name: string,
  parsed: ParsedGCode,
  draws: MoveDraw[],
  wantExtruding: boolean,
  colorAt: (z: number) => BABYLON.Color4,
  scene: BABYLON.Scene,
) {
  const { moves } = parsed;
  let vertexTotal = 0;
  for (let k = 1; k < moves.length; k++) {
    if (moves[k].extruding === wantExtruding) vertexTotal += draws[k].segments + 1;
  }

  const cumIndices = new Uint32Array(moves.length);
  if (vertexTotal === 0) return { mesh: null, cumIndices };

  const positions = new Float32Array(vertexTotal * 3);
  const colors = new Float32Array(vertexTotal * 4);
  const indices = new Uint32Array((vertexTotal - 1) * 2);
  let v = 0;
  let idx = 0;

  for (let k = 1; k < moves.length; k++) {
    const cur = moves[k];
    if (cur.extruding === wantExtruding) {
      const prev = moves[k - 1];
      const n = draws[k].segments;
      for (let s = 0; s <= n; s++) {
        const f = s / n;
        const r = prev.r + (cur.r - prev.r) * f;
        const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
        const z = prev.z + (cur.z - prev.z) * f;
        positions[v * 3] = r * Math.cos(c);
        positions[v * 3 + 1] = z;
        positions[v * 3 + 2] = r * Math.sin(c);
        const col = colorAt(z);
        colors[v * 4] = col.r;
        colors[v * 4 + 1] = col.g;
        colors[v * 4 + 2] = col.b;
        colors[v * 4 + 3] = col.a;
        if (s > 0) {
          indices[idx++] = v - 1;
          indices[idx++] = v;
        }
        v++;
      }
    }
    cumIndices[k] = idx;
  }

  const mesh = new BABYLON.LinesMesh(name, scene, null, null, undefined, true, true);
  const data = new BABYLON.VertexData();
  data.positions = positions;
  data.colors = colors;
  data.indices = indices.subarray(0, idx);
  data.applyToMesh(mesh);
  mesh.isPickable = false;
  mesh.alwaysSelectAsActiveMesh = true;
  return { mesh, cumIndices };
}

export const GCodePreview: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sceneRef = useRef<BABYLON.Scene | null>(null);
  const cameraRef = useRef<BABYLON.ArcRotateCamera | null>(null);
  const plateNodeRef = useRef<BABYLON.TransformNode | null>(null);
  const headNodeRef = useRef<BABYLON.TransformNode | null>(null);

  // Données de trajectoire : refs (pas de state) — lues à chaque frame par la boucle de rendu.
  const parsedRef = useRef<ParsedGCode | null>(null);
  const drawsRef = useRef<MoveDraw[]>([]);
  const extrudedRef = useRef<{ mesh: BABYLON.LinesMesh | null; cumIndices: Uint32Array } | null>(null);
  const travelRef = useRef<{ mesh: BABYLON.LinesMesh | null; cumIndices: Uint32Array } | null>(null);
  const tRef = useRef(0); // position de lecture, en index de mouvement fractionnaire
  const playingRef = useRef(false);
  const speedRef = useRef(SPEED_OPTIONS[1]);
  const showTravelRef = useRef(false);

  const dragDepthRef = useRef(0);
  const [isDragging, setIsDragging] = useState(false);
  const [fileInfo, setFileInfo] = useState<{ name: string; moves: number; extruding: number; minZ: number; maxZ: number; minC: number; maxC: number } | null>(null);
  const [t, setT] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(SPEED_OPTIONS[1]);
  const [showTravel, setShowTravel] = useState(false);

  useEffect(() => { playingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { speedRef.current = speed; }, [speed]);
  useEffect(() => {
    showTravelRef.current = showTravel;
    travelRef.current?.mesh?.setEnabled(showTravel);
  }, [showTravel]);

  useLayoutEffect(() => {
    if (!canvasRef.current) return;
    const canvas = canvasRef.current;
    const engine = new BABYLON.Engine(canvas, true, { preserveDrawingBuffer: true });
    const scene = new BABYLON.Scene(engine);
    sceneRef.current = scene;
    // Fond opaque : Viewport3D reste monté juste dessous et ne doit pas transparaître.
    scene.clearColor = new BABYLON.Color4(0.165, 0.176, 0.204, 1);

    const camera = new BABYLON.ArcRotateCamera('gcodeCamera', -Math.PI / 3, Math.PI / 3, 320, new BABYLON.Vector3(0, 20, 0), scene);
    camera.attachControl(canvas, true);
    camera.wheelPrecision = 3;
    camera.lowerRadiusLimit = 20;
    camera.upperRadiusLimit = 1200;
    camera.panningSensibility = 200;
    camera.minZ = 0.5;
    cameraRef.current = camera;

    const light = new BABYLON.HemisphericLight('gcodeLight', new BABYLON.Vector3(0.3, 1, 0.2), scene);
    light.intensity = 0.9;

    // Noeud du plateau : le disque, ses repères ET toute la matière déposée en sont enfants,
    // pour qu'une unique rotation les fasse tourner de façon strictement synchronisée.
    const plateNode = new BABYLON.TransformNode('plateNode', scene);
    plateNodeRef.current = plateNode;

    const plate = BABYLON.MeshBuilder.CreateDisc('plate', { radius: PLATE_RADIUS, tessellation: 128, sideOrientation: BABYLON.Mesh.DOUBLESIDE }, scene);
    plate.rotation.x = Math.PI / 2;
    plate.position.y = -0.05;
    plate.isPickable = false;
    const plateMat = new BABYLON.StandardMaterial('plateMat', scene);
    plateMat.diffuseColor = new BABYLON.Color3(0.2, 0.21, 0.24);
    plateMat.specularColor = BABYLON.Color3.Black();
    plate.material = plateMat;
    plate.parent = plateNode;

    // Repères du plateau (rayons + cercles) : sans eux la rotation d'un disque uni est invisible.
    const plateMarks: BABYLON.Vector3[][] = [];
    for (let i = 0; i < 12; i++) {
      const a = (i / 12) * Math.PI * 2;
      plateMarks.push([
        new BABYLON.Vector3(20 * Math.cos(a), 0, 20 * Math.sin(a)),
        new BABYLON.Vector3(PLATE_RADIUS * Math.cos(a), 0, PLATE_RADIUS * Math.sin(a)),
      ]);
    }
    for (const radius of [25, 50, 75, 100, PLATE_RADIUS]) {
      const ring: BABYLON.Vector3[] = [];
      for (let i = 0; i <= 128; i++) {
        const a = (i / 128) * Math.PI * 2;
        ring.push(new BABYLON.Vector3(radius * Math.cos(a), 0, radius * Math.sin(a)));
      }
      plateMarks.push(ring);
    }
    const marks = BABYLON.MeshBuilder.CreateLineSystem('plateMarks', { lines: plateMarks }, scene);
    marks.color = new BABYLON.Color3(0.34, 0.37, 0.42);
    marks.isPickable = false;
    marks.parent = plateNode;

    // Repère angulaire 0° du plateau, coloré, pour lire la valeur courante de C d'un coup d'oeil.
    const zeroMark = BABYLON.MeshBuilder.CreateLines('plateZero', {
      points: [new BABYLON.Vector3(PLATE_RADIUS - 12, 0.05, 0), new BABYLON.Vector3(PLATE_RADIUS, 0.05, 0)],
    }, scene);
    zeroMark.color = new BABYLON.Color3(1, 0.55, 0.05);
    zeroMark.parent = plateNode;

    // Demi-plan machine fixe (Y machine = 0, côté +R) dans lequel la tête se déplace.
    const headPlane = BABYLON.MeshBuilder.CreateLines('headPlane', {
      points: [
        new BABYLON.Vector3(0, 0.1, 0),
        new BABYLON.Vector3(PLATE_RADIUS + 10, 0.1, 0),
        new BABYLON.Vector3(PLATE_RADIUS + 10, PLATE_HEIGHT, 0),
        new BABYLON.Vector3(0, PLATE_HEIGHT, 0),
      ],
    }, scene);
    headPlane.color = new BABYLON.Color3(0.25, 0.5, 0.58);
    headPlane.alpha = 0.5;
    headPlane.isPickable = false;

    // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le
    // noeud est ensuite orienté pour que ce corps penche de B vers −R.
    const headNode = new BABYLON.TransformNode('headNode', scene);
    headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
    const headMat = new BABYLON.StandardMaterial('headMat', scene);
    headMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
    headMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
    const nozzle = BABYLON.MeshBuilder.CreateCylinder('headNozzle', { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
    nozzle.position.y = 4.5;
    nozzle.material = headMat;
    nozzle.parent = headNode;
    const body = BABYLON.MeshBuilder.CreateCylinder('headBody', { diameter: 14, height: 26, tessellation: 24 }, scene);
    body.position.y = 9 + 13;
    const bodyMat = new BABYLON.StandardMaterial('headBodyMat', scene);
    bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
    bodyMat.alpha = 0.55;
    body.material = bodyMat;
    body.parent = headNode;
    for (const mesh of [nozzle, body]) mesh.isPickable = false;
    headNode.setEnabled(false);
    headNodeRef.current = headNode;

    const up = BABYLON.Vector3.Up();
    const headDir = new BABYLON.Vector3();
    let uiSyncAccumulator = 0;

    scene.onBeforeRenderObservable.add(() => {
      const parsed = parsedRef.current;
      if (!parsed || parsed.moves.length === 0) return;
      const last = parsed.moves.length - 1;

      if (playingRef.current) {
        const dt = engine.getDeltaTime() / 1000;
        tRef.current = Math.min(last, tRef.current + speedRef.current * dt);
        uiSyncAccumulator += dt;
        if (tRef.current >= last) {
          playingRef.current = false;
          setIsPlaying(false);
          setT(last);
        } else if (uiSyncAccumulator > 1 / 20) {
          uiSyncAccumulator = 0;
          setT(tRef.current);
        }
      }

      const tt = tRef.current;
      const state = stateAt(parsed.moves, tt);

      // Rotation du plateau (et donc de la matière qui en est enfant). Dans le repère main
      // gauche de Babylon, rotation.y = ψ envoie un angle local θ (x = cos θ, z = sin θ) sur
      // θ − ψ. Avec ψ = C courant, un point déposé à C_dépôt se trouve à l'angle machine
      // C_dépôt − C : pile sous la tête (angle 0) au moment de son dépôt, puis entraîné avec
      // le plateau. Le signe opposé ferait apparaître la pièce en miroir.
      if (plateNodeRef.current) plateNodeRef.current.rotation.y = state.c * DEG2RAD;

      headNode.position.set(state.r, state.z, 0);
      const bRad = state.b * DEG2RAD;
      headDir.set(-Math.sin(bRad), Math.cos(bRad), 0);
      BABYLON.Quaternion.FromUnitVectorsToRef(up, headDir, headNode.rotationQuaternion!);

      // Préfixe de trajectoire affiché : mouvements terminés + fraction du mouvement en cours
      // (au sous-segment près, cohérent avec l'interpolation en C).
      const i = Math.floor(tt);
      const frac = tt - i;
      const next = Math.min(last, i + 1);
      const partialSegs = next > i ? Math.floor(frac * drawsRef.current[next].segments) * 2 : 0;
      for (const [entry, wantExtruding] of [[extrudedRef.current, true], [travelRef.current, false]] as const) {
        if (!entry?.mesh) continue;
        let count = entry.cumIndices[i];
        if (next > i && parsed.moves[next].extruding === wantExtruding) count += partialSegs;
        const sub = entry.mesh.subMeshes?.[0];
        if (sub) sub.indexCount = count;
        entry.mesh.isVisible = count > 0;
      }
    });

    engine.runRenderLoop(() => scene.render());

    const ro = new ResizeObserver(() => engine.resize());
    if (containerRef.current) ro.observe(containerRef.current);

    return () => {
      ro.disconnect();
      scene.dispose();
      engine.dispose();
      sceneRef.current = null;
      cameraRef.current = null;
      plateNodeRef.current = null;
      headNodeRef.current = null;
      extrudedRef.current = null;
      travelRef.current = null;
    };
  }, []);

  const loadFile = async (file: File) => {
    if (!/\.(gcode|gco|g|ngc)$/i.test(file.name)) {
      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
      return;
    }
    const scene = sceneRef.current;
    if (!scene) return;

    let parsed: ParsedGCode;
    try {
      parsed = parseGCode(await file.text());
    } catch {
      showError('Impossible de lire ce fichier G-code.');
      return;
    }
    if (parsed.moves.length < 2) {
      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
      return;
    }

    extrudedRef.current?.mesh?.dispose();
    travelRef.current?.mesh?.dispose();

    const draws: MoveDraw[] = parsed.moves.map((mv, k) => ({
      segments: k === 0 ? 0 : subdivisions(parsed.moves[k - 1], mv),
    }));

    const zSpan = Math.max(1e-6, parsed.maxZ - parsed.minZ);
    const low = new BABYLON.Color3(0.12, 0.42, 1);
    const high = new BABYLON.Color3(0.3, 0.95, 0.9);
    const extrudedColor = (z: number) => {
      const c = BABYLON.Color3.Lerp(low, high, (z - parsed.minZ) / zSpan);
      return new BABYLON.Color4(c.r, c.g, c.b, 1);
    };
    const travelColor = () => new BABYLON.Color4(0.75, 0.75, 0.8, 0.35);

    const extruded = buildPathMesh('extrudedPath', parsed, draws, true, extrudedColor, scene);
    const travel = buildPathMesh('travelPath', parsed, draws, false, travelColor, scene);
    extruded.mesh && (extruded.mesh.parent = plateNodeRef.current);
    if (travel.mesh) {
      travel.mesh.parent = plateNodeRef.current;
      travel.mesh.setEnabled(showTravelRef.current);
    }

    parsedRef.current = parsed;
    drawsRef.current = draws;
    extrudedRef.current = extruded;
    travelRef.current = travel;

    const last = parsed.moves.length - 1;
    tRef.current = last;
    playingRef.current = false;
    setIsPlaying(false);
    setT(last);
    headNodeRef.current?.setEnabled(true);

    const camera = cameraRef.current;
    if (camera) {
      camera.setTarget(new BABYLON.Vector3(0, (parsed.minZ + parsed.maxZ) / 2, 0));
      camera.radius = Math.max(120, Math.max(parsed.maxR, parsed.maxZ - parsed.minZ) * 3.2);
    }

    setFileInfo({
      name: file.name,
      moves: parsed.moves.length,
      extruding: parsed.extrudingCount,
      minZ: parsed.minZ,
      maxZ: parsed.maxZ,
      minC: parsed.minC,
      maxC: parsed.maxC,
    });

    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
    } else {
      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
    }
  };

  const seek = (value: number) => {
    playingRef.current = false;
    setIsPlaying(false);
    tRef.current = value;
    setT(value);
  };

  const togglePlay = () => {
    const parsed = parsedRef.current;
    if (!parsed) return;
    if (!isPlaying && tRef.current >= parsed.moves.length - 1) {
      tRef.current = 0;
      setT(0);
    }
    playingRef.current = !isPlaying;
    setIsPlaying(!isPlaying);
  };

  // Compteur d'entrées/sorties : `dragleave` se déclenche aussi en survolant un enfant.
  const handleDragEnter = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('Files')) return;
    e.preventDefault();
    dragDepthRef.current++;
    setIsDragging(true);
  };
  const handleDragOver = (e: React.DragEvent) => {
    if (!e.dataTransfer.types.includes('Files')) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };
  const handleDragLeave = () => {
    dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
    if (dragDepthRef.current === 0) setIsDragging(false);
  };
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    dragDepthRef.current = 0;
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file) loadFile(file);
  };

  const parsed = parsedRef.current;
  const current = parsed && parsed.moves.length ? stateAt(parsed.moves, t) : null;
  const currentMove = parsed ? parsed.moves[Math.min(parsed.moves.length - 1, Math.ceil(t))] : null;
  const lastIndex = fileInfo ? fileInfo.moves - 1 : 0;

  return (
    <div
      ref={containerRef}
      className={styles.container}
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <canvas ref={canvasRef} className={styles.canvas} />

      <input
        ref={fileInputRef}
        type="file"
        accept=".gcode,.gco,.g,.ngc"
        style={{ display: 'none' }}
        onChange={(e) => {
          const file = e.target.files?.[0];
          if (file) loadFile(file);
          e.target.value = '';
        }}
      />

      {!fileInfo && !isDragging && (
        <button type="button" className={styles.emptyHint} onClick={() => fileInputRef.current?.click()}>
          <Upload size={28} />
          <span className={styles.emptyHintTitle}>Glissez un fichier G-code ici</span>
          <span className={styles.emptyHintSub}>.gcode · .gco · .g · .ngc — ou cliquez pour parcourir</span>
        </button>
      )}

      {isDragging && (
        <div className={styles.dropOverlay}>
          <div className={styles.dropOverlayInner}>
            <Upload size={26} />
            <span>Déposez le fichier G-code</span>
            <span className={styles.dropOverlaySub}>.gcode, .gco, .g, .ngc</span>
          </div>
        </div>
      )}

      {fileInfo && current && (
        <div className={styles.infoPanel} data-apex-chrome-panel>
          <div className={styles.fileName}>
            <FileCode2 size={14} />
            <span>{fileInfo.name}</span>
          </div>
          <div className={styles.infoRow}><span>Mouvements</span><span className={styles.infoValue}>{fileInfo.moves.toLocaleString('fr-FR')}</span></div>
          <div className={styles.infoRow}><span>Dont extrusion</span><span className={styles.infoValue}>{fileInfo.extruding.toLocaleString('fr-FR')}</span></div>
          <div className={styles.infoRow}><span>Hauteur</span><span className={styles.infoValue}>{fileInfo.minZ.toFixed(2)} → {fileInfo.maxZ.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>Plage C</span><span className={styles.infoValue}>{fileInfo.minC.toFixed(1)}° → {fileInfo.maxC.toFixed(1)}°</span></div>
          <div className={styles.infoDivider} />
          <div className={styles.infoRow}><span>R</span><span className={styles.infoValue}>{current.r.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>C</span><span className={styles.infoValue}>{current.c.toFixed(2)}°</span></div>
          <div className={styles.infoRow}><span>Z</span><span className={styles.infoValue}>{current.z.toFixed(2)} mm</span></div>
          <div className={styles.infoRow}><span>B</span><span className={styles.infoValue}>{current.b.toFixed(1)}°</span></div>
          <div className={styles.infoRow}>
            <span>Segment</span>
            <span className={currentMove?.extruding ? styles.badgeExtrude : styles.badgeTravel}>
              {currentMove?.extruding ? 'Extrusion' : 'Trajet à vide'}
            </span>
          </div>
          <button type="button" className={styles.linkButton} onClick={() => fileInputRef.current?.click()}>
            Ouvrir un autre fichier…
          </button>
        </div>
      )}

      {fileInfo && (
        <div className={styles.controlsPanel} data-apex-chrome-panel>
          <button type="button" className={styles.playButton} onClick={togglePlay} aria-label={isPlaying ? 'Pause' : 'Lecture'}>
            {isPlaying ? <Pause size={16} /> : <Play size={16} />}
          </button>
          <input
            type="range"
            className={styles.slider}
            min={0}
            max={lastIndex}
            step={0.01}
            value={t}
            onChange={(e) => seek(parseFloat(e.target.value))}
          />
          <span className={styles.sliderLabel}>
            {Math.floor(t).toLocaleString('fr-FR')} / {lastIndex.toLocaleString('fr-FR')}
          </span>
          <select
            className={styles.speedSelect}
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
            aria-label="Vitesse de lecture"
          >
            {SPEED_OPTIONS.map((s) => (
              <option key={s} value={s}>{s} mvt/s</option>
            ))}
          </select>
          <button
            type="button"
            className={`${styles.toggleButton} ${showTravel ? styles.toggleButtonActive : ''}`}
            onClick={() => setShowTravel((s) => !s)}
          >
            Trajets à vide
          </button>
        </div>
      )}
    </div>
  );
};

