const engine = new BABYLON.NullEngine();
const scene = new BABYLON.Scene(engine);
const DEG = Math.PI / 180;
const plate = new BABYLON.TransformNode('p', scene);
const pt = new BABYLON.TransformNode('pt', scene);
pt.parent = plate;
