plate.rotation.y = C * DEG; // plateau à l'angle du dépôt
pt.computeWorldMatrix(true);
console.log('under head (expect ~50,0,0):', pt.getAbsolutePosition().toString());
plate.rotation.y = (C + 20) * DEG;
pt.computeWorldMatrix(true);
