106	  useLayoutEffect(() => {
107	    if (!canvasRef.current) return;
108	    const canvas = canvasRef.current;
109	    const engine = new BABYLON.Engine(canvas, true, { preserveDrawingBuffer: true });
110	    engineRef.current = engine;
111	    const scene = new BABYLON.Scene(engine);
112	    sceneRef.current = scene;
113	    scene.clearColor = new BABYLON.Color4(0, 0, 0, 0);
114	
115	    const camera = new BABYLON.ArcRotateCamera("camera", Math.PI / 4, Math.PI / 3, 300, new BABYLON.Vector3(0, HEIGHT / 2, 0), scene);
116	    camera.attachControl(canvas, true);
117	
118	    // Le clic gauche est réservé à la sélection rectangulaire (fenêtre de sélection, cf. plus
119	    // bas). Cette version de Babylon ne route plus les boutons souris via les propriétés
120	    // `buttons`/`panningMouseButton` de `ArcRotateCameraPointersInput` (qui n'ont plus d'effet
121	    // sur le pointeur) mais via `camera.movement.input.inputMap`, une table ordonnée
122	    // { bouton → interaction } — cf. `resolveInteraction()` dans le moteur. Ses entrées pointeur
123	    // par défaut sont [bouton 0 + Ctrl → pan], [bouton 0 → rotate], [bouton 2 → pan] ; on les
124	    // retire et on les remplace par [bouton 1 → pan] et [bouton 2 → rotate], en gardant intactes
125	    // les entrées clavier/molette/tactile du même tableau.
126	    camera.movement.input.inputMap = [
127	      ...camera.movement.input.inputMap.filter((entry) => entry.source !== "pointer"),
128	      { source: "pointer", button: 1, interaction: "pan" },
129	      { source: "pointer", button: 2, interaction: "rotate" },
130	    ];
131	
132	    /**
133	     * Zoom molette VERS LE CURSEUR, multiplicatif. Remplace l'entrée molette de Babylon :
134	     *  - multiplicatif : chaque cran change le rayon d'un même pourcentage, quelle que soit
135	     *    l'échelle (une distance fixe ne faisait rien de loin et envoyait en butée de près) ;
136	     *  - vers le curseur : le point du plan horizontal passant par la cible, sous la souris, reste
137	     *    fixe à l'écran — caméra ET cible sont rapprochées de ce point du même facteur. On avance
138	     *    donc vers ce qu'on vise sans devoir translater tous les trois crans. En modélisation ce
139	     *    plan est le sol, et la cible y reste.
140	     * `zoomToMouseLocation` de Babylon fait l'équivalent, mais son inertie s'arrête sur des seuils
141	     * ABSOLUS qui tronquent le mouvement aux petites échelles (même défaut que l'ancien pan).
142	     * L'adoucissement est donc refait ici, en échelle logarithmique, indépendant de l'échelle.
143	     */
144	    camera.inputs.removeByType("ArcRotateCameraMouseWheelInput");
145	    const ZOOM_LOG_PER_WHEEL_UNIT = 0.15 / 100; // cran standard (deltaY 100) ≈ ×1,16 / ÷1,16
146	    const ZOOM_SMOOTHING_PER_FRAME = 0.35; // part du zoom restant appliquée à chaque image (60 i/s)
147	    // Au-delà, le point visé est quasi à l'horizon : on zoome alors vers la cible, sans quoi un
148	    // cran projetterait la caméra à des kilomètres.
149	    const ZOOM_MAX_ANCHOR_DISTANCE_RADII = 20;
150	    let pendingZoomLog = 0;
151	    const zoomAnchor = new BABYLON.Vector3();
152	    const onCanvasWheel = (event: WheelEvent) => {
153	      event.preventDefault();
154	      const unit = event.deltaMode === 1 ? 33 : event.deltaMode === 2 ? 100 : 1; // lignes / pages
155	      pendingZoomLog += event.deltaY * unit * ZOOM_LOG_PER_WHEEL_UNIT;
156	    };
157	    canvas.addEventListener("wheel", onCanvasWheel, { passive: false });
158	    const zoomTowardCursorObserver = scene.onBeforeRenderObservable.add(() => {
159	      if (pendingZoomLog === 0) return;
160	      const frames = engine.getDeltaTime() / (1000 / 60);
161	      const portion = 1 - Math.pow(1 - ZOOM_SMOOTHING_PER_FRAME, Math.max(frames, 0.01));
162	      let stepLog = Math.abs(pendingZoomLog) < 1e-4 ? pendingZoomLog : pendingZoomLog * portion;
163	      pendingZoomLog -= stepLog;
164	
165	      // Respect des butées : on écrête le facteur plutôt que de laisser Babylon ramener le rayon
166	      // (ce qui décalerait le point visé).
167	      const minR = camera.lowerRadiusLimit ?? 0;
168	      const maxR = camera.upperRadiusLimit ?? Number.POSITIVE_INFINITY;
169	      const targetR = Math.min(Math.max(camera.radius * Math.exp(stepLog), minR), maxR);
170	      if (targetR === camera.radius) { pendingZoomLog = 0; return; }
171	      stepLog = Math.log(targetR / camera.radius);
172	      const factor = Math.exp(stepLog);
173	
174	      // Point visé : intersection du rayon souris avec le plan horizontal de la cible.
175	      zoomAnchor.copyFrom(camera.target);
176	      const ray = scene.createPickingRay(scene.pointerX, scene.pointerY, BABYLON.Matrix.Identity(), camera);
177	      if (Math.abs(ray.direction.y) > 1e-9) {
178	        const t = (camera.target.y - ray.origin.y) / ray.direction.y;
179	        if (t > 0 && t <= camera.radius * ZOOM_MAX_ANCHOR_DISTANCE_RADII) {
180	          ray.origin.addToRef(ray.direction.scale(t), zoomAnchor);
181	          zoomAnchor.y = camera.target.y;
182	        }
183	      }
184	      // Homothétie de centre `zoomAnchor` : cible et caméra (via le rayon) se rapprochent de lui
185	      // du même facteur, orientation inchangée — le point visé reste donc fixe à l'écran.
186	      const newTarget = zoomAnchor.add(camera.target.subtract(zoomAnchor).scale(factor));
187	      camera.target.copyFrom(newTarget);
188	      camera.radius = targetR;
189	    });
190	
191	    // Le MSAA du contexte WebGL (2ᵉ argument `true` de BABYLON.Engine) ne couvre que le
192	    // rendu direct — les contours (LinesMesh, edgesRendering des voxels) et le compositing
193	    // via blurRT restent crénelés sans une passe FXAA sur la sortie finale du pipeline.
194	    const renderPipeline = new BABYLON.DefaultRenderingPipeline("apexRenderPipeline", false, scene, [camera]);
195	    renderPipeline.fxaaEnabled = true;
196	    renderPipeline.samples = 4;
