    moves.push({ r, c, z, b, extruding });
  }

  let minZ = Infinity, maxZ = -Infinity, maxR = 0, minC = Infinity, maxC = -Infinity;
  for (const mv of moves) {
    if (mv.z < minZ) minZ = mv.z;
    if (mv.z > maxZ) maxZ = mv.z;
    if (mv.r > maxR) maxR = mv.r;
    if (mv.c < minC) minC = mv.c;
    if (mv.c > maxC) maxC = mv.c;
  }
  if (!moves.length) { minZ = maxZ = minC = maxC = 0; }

  return { moves, minZ, maxZ, maxR, minC, maxC, extrudingCount };
}

/** Position (R, C, Z, B) interpolée linéairement — comme le firmware — au temps `t` exprimé
 * en index de mouvement fractionnaire. */
export function stateAt(moves: GCodeMove[], t: number) {
  const i = Math.max(0, Math.min(moves.length - 1, Math.floor(t)));
  const a = moves[i];
  const b = moves[Math.min(moves.length - 1, i + 1)];
  const f = Math.max(0, Math.min(1, t - i));
  return {
    r: a.r + (b.r - a.r) * f,
    c: a.c + (b.c - a.c) * f,
    z: a.z + (b.z - a.z) * f,
    b: a.b + (b.b - a.b) * f,
  };
}

interface PathMesh {
  mesh: BABYLON.LinesMesh | null;
  /** Nombre d'indices à dessiner une fois le mouvement k terminé. */
  cumIndices: Uint32Array;
}

/** Construit un LinesMesh (repère plateau) contenant tous les mouvements dont `extruding`
 * vaut `wantExtruding`, dans l'ordre du fichier. N'importe quel préfixe de la trajectoire
 * s'affiche ensuite en changeant simplement `indexCount`, sans reconstruire la géométrie. */
function buildPathMesh(
  name: string,
  parsed: ParsedGCode,
  segments: Uint32Array,
  wantExtruding: boolean,
  colorAt: (z: number, out: BABYLON.Color4) => void,
  scene: BABYLON.Scene,
): PathMesh {
  const { moves } = parsed;
  let vertexTotal = 0;
  for (let k = 1; k < moves.length; k++) {
    if (moves[k].extruding === wantExtruding) vertexTotal += segments[k] + 1;
  }

  const cumIndices = new Uint32Array(moves.length);
  if (vertexTotal === 0) return { mesh: null, cumIndices };

  const positions = new Float32Array(vertexTotal * 3);
  const colors = new Float32Array(vertexTotal * 4);
  const indices = new Uint32Array((vertexTotal - 1) * 2);
  const col = new BABYLON.Color4();
  let v = 0;
  let idx = 0;

  for (let k = 1; k < moves.length; k++) {
    const cur = moves[k];
    if (cur.extruding === wantExtruding) {
      const prev = moves[k - 1];
      const n = segments[k];
      for (let s = 0; s <= n; s++) {
        const f = s / n;
        const r = prev.r + (cur.r - prev.r) * f;
        const c = (prev.c + (cur.c - prev.c) * f) * DEG2RAD;
        const z = prev.z + (cur.z - prev.z) * f;
        positions[v * 3] = r * Math.cos(c);
        positions[v * 3 + 1] = z;
        positions[v * 3 + 2] = r * Math.sin(c);
        colorAt(z, col);
        colors[v * 4] = col.r;
        colors[v * 4 + 1] = col.g;
        colors[v * 4 + 2] = col.b;
        colors[v * 4 + 3] = col.a;
        if (s > 0) {
          indices[idx++] = v - 1;
          indices[idx++] = v;
        }
        v++;
      }
    }
    cumIndices[k] = idx;
  }

  const mesh = new BABYLON.LinesMesh(name, scene, null, null, undefined, true, true);
  const data = new BABYLON.VertexData();
  data.positions = positions;
  data.colors = colors;
  data.indices = indices.subarray(0, idx);
  data.applyToMesh(mesh);
  mesh.isPickable = false;
  mesh.alwaysSelectAsActiveMesh = true;
  return { mesh, cumIndices };
}

export interface GCodeLayer {
  load(parsed: ParsedGCode): void;
  /** Position de lecture, en index de mouvement fractionnaire. */
  setTime(t: number): void;
  setShowTravel(show: boolean): void;
  setEnabled(enabled: boolean): void;
  dispose(): void;
}

/** Préfixe de nom de tous les maillages du calque (cf. exclusion de la capture du flou). */
export const GCODE_MESH_PREFIX = 'gcode';

/**
 * Calque de prévisualisation G-code posé dans une scène existante. `parent` est le repère du
 * plateau (origine au centre de sa surface) : Z = 0 du G-code y correspond.
 */
export function createGCodeLayer(scene: BABYLON.Scene, parent: BABYLON.TransformNode): GCodeLayer {
  const root = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Root`, scene);
  root.parent = parent;
  root.setEnabled(false);

  // Repère tournant du plateau : toute la matière déposée en est enfant.
  const plateNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Plate`, scene);
  plateNode.parent = root;

  // Tête : pointe de buse à l'origine du noeud, corps qui monte le long de +Y local ; le noeud
  // est ensuite orienté pour que ce corps penche de B vers −R.
  const headNode = new BABYLON.TransformNode(`${GCODE_MESH_PREFIX}Head`, scene);
  headNode.parent = root;
  headNode.rotationQuaternion = BABYLON.Quaternion.Identity();
  const nozzleMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}NozzleMat`, scene);
  nozzleMat.diffuseColor = new BABYLON.Color3(1, 0.55, 0.05);
  nozzleMat.emissiveColor = new BABYLON.Color3(0.35, 0.17, 0);
  const nozzle = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}Nozzle`, { diameterTop: 7, diameterBottom: 0.6, height: 9, tessellation: 20 }, scene);
  nozzle.position.y = 4.5;
  nozzle.material = nozzleMat;
  nozzle.parent = headNode;
  const bodyMat = new BABYLON.StandardMaterial(`${GCODE_MESH_PREFIX}HeadBodyMat`, scene);
  bodyMat.diffuseColor = new BABYLON.Color3(0.55, 0.58, 0.64);
  bodyMat.alpha = 0.55;
  const body = BABYLON.MeshBuilder.CreateCylinder(`${GCODE_MESH_PREFIX}HeadBody`, { diameter: 14, height: 26, tessellation: 24 }, scene);
  body.position.y = 9 + 13;
  body.material = bodyMat;
  body.parent = headNode;
  nozzle.isPickable = false;
  body.isPickable = false;
  headNode.setEnabled(false);

  let parsed: ParsedGCode | null = null;
  let segments = new Uint32Array(0);
  let extruded: PathMesh | null = null;
  let travel: PathMesh | null = null;
  let time = 0;
  let showTravel = false;

  const up = BABYLON.Vector3.Up();
  const headDir = new BABYLON.Vector3();

  const apply = () => {
    if (!parsed || parsed.moves.length === 0) return;
    const last = parsed.moves.length - 1;
    const t = Math.max(0, Math.min(last, time));
    const state = stateAt(parsed.moves, t);

    // Dans le repère main gauche de Babylon, rotation.y = ψ envoie un angle local θ
    // (x = cos θ, z = sin θ) sur θ − ψ. Avec ψ = C courant, un point déposé à C_dépôt est à
    // l'angle machine C_dépôt − C : pile sous la tête (angle 0) au moment de son dépôt, puis
    // entraîné avec le plateau. Le signe opposé ferait apparaître la pièce en miroir.
    plateNode.rotation.y = state.c * DEG2RAD;

    headNode.position.set(state.r, state.z, 0);
    const bRad = state.b * DEG2RAD;
    headDir.set(-Math.sin(bRad), Math.cos(bRad), 0);
    BABYLON.Quaternion.FromUnitVectorsToRef(up, headDir, headNode.rotationQuaternion!);

    // Préfixe affiché : mouvements terminés + fraction du mouvement en cours, au sous-segment
    // près (cohérent avec l'interpolation en C).
    const i = Math.floor(t);
    const next = Math.min(last, i + 1);
    const partial = next > i ? Math.floor((t - i) * segments[next]) * 2 : 0;
    for (const [entry, wantExtruding] of [[extruded, true], [travel, false]] as const) {
      if (!entry?.mesh) continue;
      let count = entry.cumIndices[i];
      if (next > i && parsed.moves[next].extruding === wantExtruding) count += partial;
      const sub = entry.mesh.subMeshes?.[0];
      if (sub) sub.indexCount = count;
      entry.mesh.isVisible = count > 0;
    }
  };

  const disposePaths = () => {
    extruded?.mesh?.dispose();
    travel?.mesh?.dispose();
    extruded = null;
    travel = null;
  };

  return {
    load(next) {
      disposePaths();
      parsed = next;
      segments = new Uint32Array(next.moves.length);
      for (let k = 1; k < next.moves.length; k++) {
        const dc = Math.abs(next.moves[k].c - next.moves[k - 1].c);
        segments[k] = Math.max(1, Math.ceil(dc / MAX_SUBSEGMENT_DEG));
      }

      // Dégradé en hauteur dans les teintes cyan de l'interface.
      const zSpan = Math.max(1e-6, next.maxZ - next.minZ);
      const low = new BABYLON.Color3(0.1, 0.45, 1);
      const high = new BABYLON.Color3(0.3, 0.95, 1);
      const extrudedColor = (z: number, out: BABYLON.Color4) => {
        const f = (z - next.minZ) / zSpan;
        out.set(low.r + (high.r - low.r) * f, low.g + (high.g - low.g) * f, low.b + (high.b - low.b) * f, 1);
      };
      const travelColor = (_z: number, out: BABYLON.Color4) => { out.set(0.8, 0.8, 0.85, 0.35); };

      extruded = buildPathMesh(`${GCODE_MESH_PREFIX}Extruded`, next, segments, true, extrudedColor, scene);
      travel = buildPathMesh(`${GCODE_MESH_PREFIX}Travel`, next, segments, false, travelColor, scene);
      if (extruded.mesh) extruded.mesh.parent = plateNode;
      if (travel.mesh) {
        travel.mesh.parent = plateNode;
        travel.mesh.setEnabled(showTravel);
      }

      headNode.setEnabled(next.moves.length > 0);
      time = next.moves.length - 1;
      apply();
    },
    setTime(t) {
      time = t;
      apply();
    },
    setShowTravel(show) {
      showTravel = show;
      travel?.mesh?.setEnabled(show);
    },
    setEnabled(enabled) {
      root.setEnabled(enabled);
    },
    dispose() {
      disposePaths();
      root.dispose(false, true);
    },
  };
}

