import * as BABYLON from 'babylonjs';
import { parseGCode, createGCodeLayer } from '../../../../../../../../../APEX_NEW_VERSION/slicer_ux/src/components/gcodeLayer';

// G-code synthétique : trajet à vide, puis un arc extrudé de C=350 à 370 (franchit 360, non replié)
const lines = ['; test', 'G00 Y350 X40 Z0.2 B0 F3000', 'G00 Y350 X40 Z0.2 B0 E0 F3000'];
let e = 0;
for (let c = 351; c <= 370; c++) { e += 0.05; lines.push(`G00 Y${c} X40 Z0.2 B10 E${e.toFixed(3)} F1200`); }
lines.push('G00 Y370 X40 Z5 B30 F6000'); // trajet à vide
const parsed = parseGCode(lines.join('\n'));
console.log('moves', parsed.moves.length, 'extruding', parsed.extrudingCount, 'C range', parsed.minC, parsed.maxC);

const engine = new BABYLON.NullEngine();
const scene = new BABYLON.Scene(engine);
const anchor = new BABYLON.TransformNode('a', scene);
const layer = createGCodeLayer(scene, anchor);
layer.load(parsed);
const ext = scene.getMeshByName('gcodeExtruded')!;
const trv = scene.getMeshByName('gcodeTravel')!;
console.log('extruded indices drawn at end:', ext.subMeshes[0].indexCount, '/', ext.getTotalIndices(), '(20 moves x2 subsegs x2 = 80)');
layer.setTime(2);
console.log('t=2 extruded drawn:', ext.subMeshes[0].indexCount, 'visible', ext.isVisible);
layer.setTime(2.5);
console.log('t=2.5 extruded drawn:', ext.subMeshes[0].indexCount, '(expect 2 + 2)');
// Le dernier point déposé doit se trouver sous la tête (angle machine 0)
layer.setTime(21);
const plate = scene.getTransformNodeByName('gcodePlate')!;
plate.computeWorldMatrix(true);
const p = BABYLON.Vector3.TransformCoordinates(new BABYLON.Vector3(40 * Math.cos(370 * Math.PI / 180), 0.2, 40 * Math.sin(370 * Math.PI / 180)), plate.getWorldMatrix());
const head = scene.getTransformNodeByName('gcodeHead')!;
console.log('last deposit world', p.toString(), 'head', head.position.toString());
console.log('travel mesh enabled (default hidden):', trv.isEnabled());

