const { chromium } = require('playwright-core');
const fs = require('fs');
const path = require('path');
const out = __dirname;

// Tube hélicoïdal : 20 couches, C oscille dans ±15° autour de 0 (plage étroite réaliste)
const lines = ['; test apex', 'G00 Y0 X30 Z0.2 B0 F3000'];
let e = 0;
for (let layer = 0; layer < 20; layer++) {
  const z = (0.2 + layer * 0.4).toFixed(2);
  for (let s = 0; s <= 120; s++) {
    const c = (Math.sin((s / 120) * Math.PI * 2) * 15).toFixed(2);
    const r = (30 + 10 * Math.cos((s / 120) * Math.PI * 2)).toFixed(2);
    e += 0.03;
    lines.push(`G00 Y${c} X${r} Z${z} B${(layer * 2).toFixed(1)} E${e.toFixed(3)} F1200`);
  }
}
fs.writeFileSync(path.join(out, 'test.gcode'), lines.join('\n'));

(async () => {
  const browser = await chromium.launch({ channel: 'chrome', headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
  page.on('console', (m) => { if (['error', 'warning'].includes(m.type())) console.log('[console]', m.type(), m.text().slice(0, 300)); });
  page.on('pageerror', (e) => console.log('[pageerror]', e.stack));
  await page.goto('http://localhost:8093/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.evaluate(() => {
    window.__timeEvents = 0;
    window.addEventListener('apex-gcode-time', () => { window.__timeEvents++; });
  });
  await page.getByRole('button', { name: 'Prévisualisation' }).first().click();
  await page.waitForTimeout(3500);
  await page.setInputFiles('input[accept=".gcode,.gco,.g,.ngc"]', path.join(out, 'test.gcode'));
  await page.waitForTimeout(1500);
  await page.screenshot({ path: path.join(out, '1-loaded.png') });

  const slider = page.locator('input[type=range]');
  const box = await slider.boundingBox();
  console.log('slider box', box, 'value', await slider.inputValue());
  await page.mouse.move(box.x + box.width - 3, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * 0.3, box.y + box.height / 2, { steps: 10 });
  await page.mouse.up();
  await page.waitForTimeout(500);
  console.log('after drag value', await slider.inputValue(), 'timeEvents', await page.evaluate(() => window.__timeEvents));
  await page.screenshot({ path: path.join(out, '2-dragged.png') });

  await page.getByRole('button', { name: /Lecture|Pause/ }).click();
  await page.waitForTimeout(1200);
  console.log('after play value', await slider.inputValue(), 'timeEvents', await page.evaluate(() => window.__timeEvents));
  await page.screenshot({ path: path.join(out, '3-playing.png') });
  await browser.close();
})();

