// Même verre dépoli que les autres panneaux flottants (cf. barre de statut d'Index.tsx).
@mixin glass-panel {
  background: rgba(10, 15, 26, 0.45);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border-radius: 14px;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
}

$accent: #38bdf8;
$text: #e4e7ec;
$muted: #9ca3af;

// Calque d'interface au-dessus du viewport (le rendu 3D reste celui de Viewport3D) : il laisse
// passer la souris vers la caméra, seuls ses panneaux la captent. Sous le rideau de transition
// (SpaceTransitionOverlay, z-index 30).
.container {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;

  > * {
    pointer-events: auto;
  }
}

.emptyHint {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 36px 48px;
  border: 2px dashed rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.2);
  color: $muted;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;

  &:hover {
    border-color: rgba(56, 189, 248, 0.5);
    color: $accent;
  }
}

.emptyHintTitle {
  font-size: 14px;
  font-weight: 500;
  color: $text;
}

.emptyHintSub {
  font-size: 12px;
  color: $muted;
}

.dropOverlay {
  position: absolute;
  inset: 12px;
  z-index: 20;
  border: 2px dashed rgba(56, 189, 248, 0.6);
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none !important;
}

.dropOverlayInner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: $text;
  font-size: 15px;
  font-weight: 500;
}

.dropOverlaySub {
  font-size: 12px;
  font-weight: 400;
  color: $muted;
}

// Même emplacement que CategoriesSidebar, qui se masque en mode Prévisualisation.
.infoPanel {
  @include glass-panel;
  position: absolute;
  top: 212px;
  left: 24px;
  z-index: 10;
  padding: 12px 16px;
  color: $text;
  font-size: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 250px;
}

.fileName {
  display: flex;
  align-items: center;
  gap: 6px;
  color: $accent;
  font-weight: 600;
  font-size: 13px;
