  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.infoRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  color: $muted;
}

.infoValue {
  color: $text;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.infoDivider {
  height: 1px;
  margin: 2px 0;
  background: rgba(255, 255, 255, 0.08);
}

%badge {
  font-size: 11px;
  font-weight: 500;
  padding: 1px 8px;
  border-radius: 999px;
}

.badgeExtrude {
  @extend %badge;
  color: $accent;
  background: rgba(56, 189, 248, 0.14);
}

.badgeTravel {
  @extend %badge;
  color: $muted;
  background: rgba(255, 255, 255, 0.08);
}

.linkButton {
  margin-top: 4px;
