  color: $muted;
  font-size: 11px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;

  &:hover {
    color: $accent;
  }
}

// Entre FileSidebar/coin gauche et SliceSidebar (bas droit, 293px + marge 24px).
.controlsPanel {
  @include glass-panel;
  position: absolute;
  bottom: 24px;
