1	"use client";
2	
3	import React, { useEffect, useRef, useState } from 'react';
4	import { Play, Pause, Upload, FileCode2 } from 'lucide-react';
5	import { showError, showSuccess, showWarning } from '@/utils/toast';
6	import { parseGCode, stateAt, SUSPICIOUS_C_RANGE_DEG, type ParsedGCode } from './gcodeLayer';
7	import styles from './GCodePreview.module.scss';
8	
9	/**
10	 * Interface de l'espace Prévisualisation : dépôt de fichier G-code, infos et lecture. Le rendu
11	 * 3D est fait par Viewport3D, dans sa propre scène (même plateau, même grille qu'en
12	 * Préparation), piloté par les événements :
13	 *  - `apex-gcode-loaded` { parsed } : nouvelle trajectoire à afficher ;
14	 *  - `apex-gcode-time` { t } : position de lecture (index de mouvement fractionnaire) ;
15	 *  - `apex-gcode-show-travel` { show } : affichage des trajets à vide.
16	 */
17	
18	const SPEED_OPTIONS = [25, 100, 400, 1600, 6400]; // mouvements par seconde
19	const ACCEPTED_EXT = /\.(gcode|gco|g|ngc)$/i;
20	
21	const dispatchTime = (t: number) =>
22	  window.dispatchEvent(new CustomEvent('apex-gcode-time', { detail: { t } }));
23	
24	interface GCodePreviewProps {
25	  /** Espace Prévisualisation affiché. */
26	  active: boolean;
27	}
28	
29	export const GCodePreview: React.FC<GCodePreviewProps> = ({ active }) => {
30	  const fileInputRef = useRef<HTMLInputElement>(null);
31	  const parsedRef = useRef<ParsedGCode | null>(null);
32	  const tRef = useRef(0);
33	  const dragDepthRef = useRef(0);
34	
35	  const [fileInfo, setFileInfo] = useState<{ name: string; moves: number; extruding: number; minZ: number; maxZ: number; minC: number; maxC: number } | null>(null);
36	  const [t, setT] = useState(0);
37	  const [isPlaying, setIsPlaying] = useState(false);
38	  const [speed, setSpeed] = useState(SPEED_OPTIONS[1]);
39	  const [showTravel, setShowTravel] = useState(false);
40	  const [isDragging, setIsDragging] = useState(false);
41	
42	  useEffect(() => {
43	    if (!active) setIsPlaying(false);
44	  }, [active]);
45	
46	  useEffect(() => {
47	    window.dispatchEvent(new CustomEvent('apex-gcode-show-travel', { detail: { show: showTravel } }));
48	  }, [showTravel]);
49	
50	  // Horloge de lecture : avance `t` à `speed` mouvements/s, pousse chaque image au viewport et
51	  // rafraîchit l'affichage React à ~20 Hz seulement.
52	  useEffect(() => {
53	    if (!isPlaying) return;
54	    const parsed = parsedRef.current;
55	    if (!parsed) return;
56	    const last = parsed.moves.length - 1;
57	    let raf = 0;
58	    let prev = performance.now();
59	    let sinceUiSync = 0;
60	    const step = (now: number) => {
61	      const dt = (now - prev) / 1000;
62	      prev = now;
63	      tRef.current = Math.min(last, tRef.current + speed * dt);
64	      dispatchTime(tRef.current);
65	      sinceUiSync += dt;
66	      if (tRef.current >= last) {
67	        setT(last);
68	        setIsPlaying(false);
69	        return;
70	      }
71	      if (sinceUiSync > 1 / 20) {
72	        sinceUiSync = 0;
73	        setT(tRef.current);
74	      }
75	      raf = requestAnimationFrame(step);
76	    };
77	    raf = requestAnimationFrame(step);
78	    return () => cancelAnimationFrame(raf);
79	  }, [isPlaying, speed]);
80	
81	  const loadFile = async (file: File) => {
82	    if (!ACCEPTED_EXT.test(file.name)) {
83	      showError('Format non supporté. Utilisez un fichier .gcode, .gco, .g ou .ngc.');
84	      return;
85	    }
86	    let parsed: ParsedGCode;
87	    try {
88	      parsed = parseGCode(await file.text());
89	    } catch {
90	      showError('Impossible de lire ce fichier G-code.');
91	      return;
92	    }
93	    if (parsed.moves.length < 2) {
94	      showError('Aucune trajectoire G00 exploitable dans ce fichier.');
95	      return;
96	    }
97	
98	    parsedRef.current = parsed;
99	    const last = parsed.moves.length - 1;
100	    tRef.current = last;
101	    setIsPlaying(false);
102	    setT(last);
103	    window.dispatchEvent(new CustomEvent('apex-gcode-loaded', { detail: { parsed } }));
104	
105	    setFileInfo({
106	      name: file.name,
107	      moves: parsed.moves.length,
108	      extruding: parsed.extrudingCount,
109	      minZ: parsed.minZ,
110	      maxZ: parsed.maxZ,
111	      minC: parsed.minC,
112	      maxC: parsed.maxC,
113	    });
114	
115	    if (parsed.maxC - parsed.minC > SUSPICIOUS_C_RANGE_DEG) {
116	      showWarning(`L'angle C dérive sur ${(parsed.maxC - parsed.minC).toFixed(0)}° : ce fichier vient probablement d'une version boguée du générateur.`);
117	    } else {
118	      showSuccess(`G-code chargé : ${parsed.moves.length} mouvements.`);
119	    }
120	  };
121	
122	  // Dépôt de fichier sur toute la fenêtre tant que l'espace est affiché : le viewport garde la
123	  // souris pour la caméra, cette couche ne capte donc pas les événements pointeur.
124	  useEffect(() => {
125	    if (!active) return;
126	    const hasFiles = (e: DragEvent) => !!e.dataTransfer?.types.includes('Files');
127	    const onDragEnter = (e: DragEvent) => {
128	      if (!hasFiles(e)) return;
129	      e.preventDefault();
130	      dragDepthRef.current++;
131	      setIsDragging(true);
132	    };
133	    const onDragOver = (e: DragEvent) => {
134	      if (!hasFiles(e)) return;
135	      e.preventDefault();
136	      if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
137	    };
138	    // Compteur : `dragleave` se déclenche aussi en passant d'un élément à un de ses enfants.
139	    const onDragLeave = (e: DragEvent) => {
140	      if (!hasFiles(e)) return;
141	      dragDepthRef.current = Math.max(0, dragDepthRef.current - 1);
142	      if (dragDepthRef.current === 0) setIsDragging(false);
143	    };
144	    const onDrop = (e: DragEvent) => {
