// Même verre dépoli que les autres panneaux flottants (cf. barre de statut d'Index.tsx).
@mixin glass-panel {
  background: rgba(10, 15, 26, 0.45);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border-radius: 14px;
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.4), 0 2px 8px 0 rgba(0, 0, 0, 0.3);
}

$accent: #38bdf8;
$text: #e4e7ec;
$muted: #9ca3af;

// Calque d'interface au-dessus du viewport (le rendu 3D reste celui de Viewport3D) : il laisse
// passer la souris vers la caméra, seuls ses panneaux la captent. Sous le rideau de transition
// (SpaceTransitionOverlay, z-index 30).
.container {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;

  > * {
    pointer-events: auto;
  }
}

.emptyHint {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 36px 48px;
  border: 2px dashed rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.2);
  color: $muted;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;

  &:hover {
    border-color: rgba(56, 189, 248, 0.5);
    color: $accent;
  }
}

.emptyHintTitle {
  font-size: 14px;
  font-weight: 500;
  color: $text;
}

.emptyHintSub {
  font-size: 12px;
  color: $muted;
}

.dropOverlay {
  position: absolute;
  inset: 12px;
  z-index: 20;
  border: 2px dashed rgba(56, 189, 248, 0.6);
  border-radius: 20px;
  background: rgba(10, 15, 26, 0.35);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none !important;
}

.dropOverlayInner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: $text;
  font-size: 15px;
  font-weight: 500;
}

.dropOverlaySub {
  font-size: 12px;
  font-weight: 400;
  color: $muted;
}

// Même emplacement que CategoriesSidebar, qui se masque en mode Prévisualisation.
.infoPanel {
  @include glass-panel;
  position: absolute;
  top: 212px;
  left: 24px;
  z-index: 10;
  padding: 12px 16px;
  color: $text;
  font-size: 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 250px;
}

.fileName {
  display: flex;
  align-items: center;
  gap: 6px;
  color: $accent;
  font-weight: 600;
  font-size: 13px;
  margin-bottom: 2px;

  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.infoRow {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  color: $muted;
}

.infoValue {
  color: $text;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.infoDivider {
  height: 1px;
  margin: 2px 0;
  background: rgba(255, 255, 255, 0.08);
}

%badge {
  font-size: 11px;
  font-weight: 500;
  padding: 1px 8px;
  border-radius: 999px;
}

.badgeExtrude {
  @extend %badge;
  color: $accent;
  background: rgba(56, 189, 248, 0.14);
}

.badgeTravel {
  @extend %badge;
  color: $muted;
  background: rgba(255, 255, 255, 0.08);
}

.linkButton {
  margin-top: 4px;
  align-self: flex-start;
  background: none;
  border: none;
  padding: 0;
  color: $muted;
  font-size: 11px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 2px;

  &:hover {
    color: $accent;
  }
}

// Au-dessus de la barre d'aide centrée en bas (TopRightMenu : bottom 24px, min-height 44px,
// z-index 1000 — elle recouvrait la barre de lecture et captait la souris) et à gauche de
// SliceSidebar (bas droit, 293px + marge 24px).
.controlsPanel {
  @include glass-panel;
  position: absolute;
  bottom: calc(24px + 44px + 12px);
  left: 24px;
  right: calc(24px + 293px + 16px);
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
}

.playButton {
  background: transparent;
  border: none;
  color: $text;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  border-radius: 8px;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba(56, 189, 248, 0.15);
    color: $accent;
  }
}

.slider {
  flex: 1;
  min-width: 80px;
  appearance: none;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  outline: none;
  cursor: pointer;

  &::-webkit-slider-thumb {
    appearance: none;
    width: 13px;
    height: 13px;
    border-radius: 50%;
    background: $accent;
    box-shadow: 0 0 6px rgba(56, 189, 248, 0.6);
  }

  &::-moz-range-thumb {
    width: 13px;
    height: 13px;
    border: none;
    border-radius: 50%;
    background: $accent;
    box-shadow: 0 0 6px rgba(56, 189, 248, 0.6);
  }
}

.sliderLabel {
  color: $muted;
  font-size: 11px;
  min-width: 96px;
  text-align: right;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.speedSelect {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: $text;
  font-size: 11px;
  padding: 4px 6px;
  border-radius: 8px;
  outline: none;
  cursor: pointer;

  option {
    background: #1b1e24;
  }
}

.toggleButton {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: $muted;
  cursor: pointer;
  font-size: 11px;
  padding: 5px 10px;
  border-radius: 8px;
  white-space: nowrap;
  transition: all 0.15s ease;

  &:hover {
    color: $text;
    border-color: rgba(255, 255, 255, 0.24);
  }
}

.toggleButtonActive {
  color: $accent;
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(56, 189, 248, 0.1);
}

