.container {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 1000;
  pointer-events: none;
}

// Espace Prévisualisation : coin bas gauche, juste au-dessus de la barre de statut d'Index.tsx
// (bottom 16px, ~32px de haut), alignée sur son bord gauche.
.containerPreview {
  left: 16px;
  bottom: 72px;
  transform: none;
  align-items: flex-start;
}

.toolbar {
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
  // Pas de `transition: all` : le déplacement entre espaces est une animation de mise en page
  // framer-motion (transform), qu'une transition CSS sur `transform` ferait traîner.
  transition: background-color 0.3s cubic-bezier(0.4, 0, 0.2, 1);

  background: rgba(10, 15, 26, 0.25);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: none;
  // `border-radius` et `box-shadow` sont posés en style inline par TopRightMenu.tsx.
  padding: 10px 24px;
  width: auto;
  max-width: 90vw;
  white-space: nowrap;
}

.toolbarPreview {
  width: 666px;
  max-width: calc(100vw - 32px);
}

.secondaryToolbar {
  min-height: 44px;
}

.infoDisplayBottom {
  font-family: 'Oxanium', sans-serif !important;
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.9);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
}

