const { chromium } = require('playwright-core');
(async () => {
  const b = await chromium.launch({ channel: 'chrome', headless: true, args: ['--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
  const p = await b.newPage({ viewport: { width: 1600, height: 900 } });
  p.on('pageerror', e => console.log('[pageerror]', e.message));
  await p.goto('http://localhost:8093/', { waitUntil: 'networkidle' }); await p.waitForTimeout(1500);
  const start = () => p.evaluate(() => { window.__s = []; const t0 = performance.now(); const tip = document.querySelector('[class*=secondaryToolbar]');
    const st = [...document.querySelectorAll('span')].find(s => s.textContent.includes('Aucun modèle')).parentElement;
    const f = () => { const r = tip.getBoundingClientRect(), q = st.getBoundingClientRect(); window.__s.push([Math.round(performance.now() - t0), 'tip', Math.round(r.left), Math.round(innerHeight - r.bottom), 'status top', Math.round(innerHeight - q.top), 'bottom', Math.round(innerHeight - q.bottom)]); if (performance.now() - t0 < 4500) requestAnimationFrame(f); }; requestAnimationFrame(f); });
  const dump = async () => { await p.waitForTimeout(4700); const s = await p.evaluate(() => window.__s); let prev = ''; for (const r of s) { const k = r.slice(1).join(' '); if (k !== prev) console.log(r.join(' ')); prev = k; } };
  await start(); await p.getByRole('button', { name: 'Prévisualisation' }).first().click();
  await p.waitForTimeout(1300); await p.screenshot({ path: 'curtain.png' }); await dump();
  await start(); await p.getByRole('button', { name: 'Préparation' }).first().click(); await dump();
  await b.close();
})();
